import compose from 'lodash/flowRight'
import {Suspense} from 'react'
import {connect} from 'react-redux'

import type {State} from '../../../../../../../reducers/types'
import {emptyArray} from '../../../../../../../utils/empty'
import {
  getBuildProblem,
  getBuildProblemInvestigations,
  getBuildProblemMutes,
} from '../../../BuildProblems.selectors'

import BuildProblemActions from './BuildProblemActions'
import type {ComposeProps, OwnProps, Props, StateProps} from './BuildProblemActions.types'

const mapStateToProps = (state: State, {buildProblemId}: OwnProps & ComposeProps): StateProps => {
  const problemOccurrence = getBuildProblem(state, buildProblemId)?.problemOccurrence
  const mutes = getBuildProblemMutes(state, buildProblemId) ?? emptyArray
  const investigations = getBuildProblemInvestigations(state, buildProblemId) ?? emptyArray

  return {
    targetId: problemOccurrence?.problem?.id,
    buildId: problemOccurrence?.build?.id,
    logAnchor: problemOccurrence?.logAnchor ?? '',
    investigations,
    mutes,
  }
}

export default compose(connect(mapStateToProps))(function BuildProblemActionsContainer(
  props: Props,
) {
  return (
    <Suspense>
      <BuildProblemActions {...props} />
    </Suspense>
  )
})
