import {memo} from 'react'

import {UserProperties} from '../../../utils/userProperties'
import ModeSwitch, {Mode} from '../ModeSwitch/ModeSwitch'

import {muteFilterItems} from './MuteStatusFilter.utils'

function MuteStatusFilter() {
  return (
    <ModeSwitch
      userProperty={UserProperties.PROBLEMS_MUTE_MODE}
      preserveParams={({mode, projectTab, currentlyFailing, assignee}) => ({
        projectTab,
        mode,
        currentlyFailing,
        assignee,
      })}
      param="muted"
    >
      {muteFilterItems.map(({key, label, value}) => (
        <Mode key={key} mode={value} label={label} />
      ))}
    </ModeSwitch>
  )
}
export default memo(MuteStatusFilter)
