import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import type {SyntheticEvent} from 'react'
import {memo, useCallback, useMemo} from 'react'

import {useAppSelector} from '../../../../../../hooks/react-redux'
import {useHeightResizeObserver} from '../../../../../../hooks/useResizeObserver'
import {getProject} from '../../../../../../selectors'
import type {ProblemOccurrenceId, ProjectId} from '../../../../../../types'
import BuildNumberContainer from '../../../../../common/BuildNumber/BuildNumber.container'
import BuildChangesDropdown from '../../../../Changes/BuildChangesDropdown/BuildChangesDropdown'
import {BuildProblemInvestigationHistoryPopupDummy} from '../../../../InvestigationHistory/BuildProblemInvestigationHistoryPopup/BuildProblemInvestigationHistoryPopup'
import Investigations from '../../../Investigations/Investigations'
import TableRow from '../../../TableRow/TableRow'
import {getBuildProblem, getBuildProblemInvestigations} from '../../BuildProblems.selectors'

import BuildProblemActions from './BuildProblemActions/BuildProblemActions.container'
import BuildProblemDetails from './BuildProblemDetails/BuildProblemDetails'
import BuildProblemName from './BuildProblemName/BuildProblemName'
import BuildProblemStatus from './BuildProblemStatus/BuildProblemStatus'

import styles from './BuildProblemRow.module.css'

type Props = {
  projectId?: ProjectId | null
  buildProblemId: ProblemOccurrenceId
  compact?: boolean
  checked: boolean
  expanded?: boolean
  onToggleSelected: (id: string) => void
  onToggleExpanded: (id?: ProblemOccurrenceId | null) => void
  onSaveMuteInvestigation: () => void
}

function BuildProblemRow({
  projectId,
  buildProblemId,
  compact,
  checked,
  expanded,
  onToggleSelected,
  onToggleExpanded,
  onSaveMuteInvestigation,
}: Props) {
  const [innerHeight, measureRef] = useHeightResizeObserver()

  const toggleSelect = useCallback(
    (event: SyntheticEvent) => {
      event.stopPropagation()
      if (buildProblemId) {
        onToggleSelected(buildProblemId)
      }
    },
    [onToggleSelected, buildProblemId],
  )

  const toggleExpand = useCallback(() => {
    if (buildProblemId) {
      onToggleExpanded(buildProblemId)
    }
  }, [onToggleExpanded, buildProblemId])

  const entry = useAppSelector(state => getBuildProblem(state, buildProblemId))
  const investigations = useAppSelector(state =>
    getBuildProblemInvestigations(state, buildProblemId),
  )

  const problemId = entry?.problemOccurrence?.problem?.id
  const details = entry?.problemOccurrence?.details
  const {id: buildId, buildTypeId} = entry?.build ?? {}
  const projectInternalId = useAppSelector(state => getProject(state, projectId)?.internalId)

  const renderSummary = useMemo(
    () => (
      <>
        <div className={styles.statusColumn}>
          <Checkbox checked={checked} onChange={toggleSelect} aria-label="Select build problem" />
          <BuildProblemStatus buildProblemId={buildProblemId} />
        </div>

        <div className={styles.buildColumn}>
          <BuildNumberContainer buildId={buildId} hideStar className={styles.number} />
        </div>

        <div className={styles.problemNameColumn}>
          <BuildProblemName buildProblemId={buildProblemId} fullText={expanded} compact={compact} />
        </div>

        <div className={styles.changesColumn}>
          {buildId && <BuildChangesDropdown buildId={buildId} />}
          {compact && (
            <div className={styles.assigned}>
              <Investigations
                investigations={investigations}
                expanded={expanded}
                onToggle={toggleExpand}
              />
            </div>
          )}
        </div>
        {!compact && (
          <div className={styles.assignedColumn}>
            <Investigations
              investigations={investigations}
              expanded={expanded}
              onToggle={toggleExpand}
            />
          </div>
        )}
        <div className={styles.actionsColumn}>
          <BuildProblemActions
            projectId={projectId}
            buildProblemId={buildProblemId}
            onSaveMuteInvestigation={onSaveMuteInvestigation}
          />
        </div>
      </>
    ),
    [
      checked,
      toggleSelect,
      buildProblemId,
      buildId,
      expanded,
      compact,
      investigations,
      toggleExpand,
      projectId,
      onSaveMuteInvestigation,
    ],
  )

  return (
    <>
      <TableRow
        label={`Problem ${buildProblemId}`}
        expanded={expanded}
        summary={renderSummary}
        onToggleExpanded={toggleExpand}
      >
        <div style={{height: innerHeight}} className={styles.outerContainer}>
          <div ref={measureRef} className={styles.innerContainer}>
            <BuildProblemDetails buildId={buildId} buildProblemId={buildProblemId} />
          </div>
        </div>
      </TableRow>
      <BuildProblemInvestigationHistoryPopupDummy
        problemOccurrenceId={buildProblemId}
        buildId={buildId}
        projectId={projectId}
        projectInternalId={projectInternalId}
        buildTypeId={buildTypeId}
        problemId={problemId}
        problemName={details}
      />
    </>
  )
}

export default memo(BuildProblemRow)
