import {memo} from 'react'

import {useAppSelector} from '../../../../../../../hooks/react-redux'
import type {TestId} from '../../../../../../../types'
import ProblemStatus from '../../../../ProblemStatus/ProblemStatus'
import {getTestProblemInvestigations, getTestProblemMutes} from '../../../TestProblems.selectors'

type Props = {
  testId?: TestId
}

function TestStatus({testId}: Props) {
  const mutes = useAppSelector(state => getTestProblemMutes(state, testId))
  const investigations = useAppSelector(state => getTestProblemInvestigations(state, testId))

  return <ProblemStatus mutes={mutes} investigations={investigations} />
}

export default memo(TestStatus)
