import Button from '@jetbrains/ring-ui-built/components/button/button'
import classNames from 'classnames'
import {memo, useCallback} from 'react'

import EntityPath from '../../../../containers/EntityPath'
import TransformText from '../../../../containers/TransformText'
import useMyId from '../../../../hooks/useMyId'
import type {Investigation} from '../../../../services/rest'
import type {BuildTypeId, ProjectId} from '../../../../types'
import {stringifyId} from '../../../../types'

import {getAssigneeName, getAssignmentName, isSelfAssigned} from './Investigations.utils'

import styles from './Investigations.module.css'

const BY = 'by '
const TO = ' to '

type Props = {
  investigations?: readonly Investigation[]
  expanded?: boolean
  onToggle?: () => void
}

function Investigations({investigations, expanded, onToggle}: Props) {
  const currentUserId = useMyId()

  const renderEntityPath = useCallback(
    (data: {projectId?: ProjectId; buildTypeId?: BuildTypeId}) => {
      const key = `investigation_${stringifyId(data.projectId) ?? stringifyId(data.buildTypeId)}`
      return (
        <EntityPath
          key={key}
          className={classNames(styles.entityPath, {[styles.fullPath]: expanded})}
          linkClassName={classNames(styles.entityPathLink, {[styles.fullPath]: expanded})}
          projectOrBuildTypeNode={{nodeType: 'all'}}
          withLeafStatusIcon={false}
          {...data}
        />
      )
    },
    [expanded],
  )

  const renderInvestigation = useCallback(
    (investigation: Investigation) => {
      const {id, assignment, assignee, scope} = investigation
      const isAssignedToCurrentUser = assignee?.id === currentUserId
      const assigneeName = getAssigneeName(investigation, isAssignedToCurrentUser)
      const selfAssigned = isSelfAssigned(investigation)
      const assignmentName = getAssignmentName(investigation)
      const scopeList = []
      const scopeProjectId = scope?.project?.id
      if (scopeProjectId != null) {
        scopeList.push({projectId: scopeProjectId})
      }
      const scopeBuildTypes = scope?.buildTypes?.buildType ?? []
      scopeBuildTypes.forEach(buildType => {
        scopeList.push({buildTypeId: buildType.id})
      })

      return (
        <div key={id}>
          <div className={classNames(styles.assignment, {[styles.full]: expanded})}>
            {!selfAssigned && <span className={styles.detail}>{BY}</span>}
            {assignmentName}
            <span className={styles.detail}>{TO}</span>
            {assigneeName}
          </div>
          {assignment?.text && (
            <TransformText
              className={styles.detail}
              text={assignment.text}
              lineHeight={16}
              lines={expanded ? null : 1}
              showPlaceholder
              withToggleButton={false}
            />
          )}
          {investigations?.length && expanded && (
            <div className={styles.scopeList}>{scopeList.map(item => renderEntityPath(item))}</div>
          )}
        </div>
      )
    },
    [currentUserId, expanded, investigations?.length, renderEntityPath],
  )

  if (!investigations?.length) {
    return null
  }

  return (
    <div className={styles.container}>
      {investigations.map(investigation => renderInvestigation(investigation))}
      <div>
        <Button className={styles.showButton} inline onClick={onToggle}>
          {expanded ? 'Show less' : 'Show more'}
        </Button>
      </div>
    </div>
  )
}

export default memo(Investigations)
