import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import classNames from 'classnames'
import {memo, Suspense, useCallback, useEffect} from 'react'
import {useLocation} from 'react-router'

import {useAppSelector} from '../../../../../hooks/react-redux'
import {useQueryParamState} from '../../../../../hooks/routes'
import {useMyUsername} from '../../../../../hooks/useMyUsername'
import {usePermission} from '../../../../../hooks/usePermission'
import {useThrottle} from '../../../../../hooks/useThrottle'
import {getProject} from '../../../../../selectors'
import {restApi} from '../../../../../services/rest'
import type {NormalizedProject, ProjectId, TestId} from '../../../../../types'
import {Permission, stringifyId} from '../../../../../types'
import {emptyArray} from '../../../../../utils/empty'
import {subscribeOnProjectEvents} from '../../../../../utils/subscriber'
import {
  TEST_MUTE_UPDATED,
  TEST_RESPONSIBILITY_CHANGED,
} from '../../../../../utils/subscriptionEvents'
import Grid from '../../../../common/Grid/Grid'
import Pager from '../../../../common/Pager/Pager.container'
import {usePage} from '../../../../common/Pager/Pager.hooks'
import {getPager} from '../../../../common/Pager/Pager.selectors'
import {PagerGroup} from '../../../../common/Pager/Pager.types'
import TestProblemPagerWarning from '../../../../common/Pager/TestProblemPager/TestProblemPagerWarning'
import Placeholder from '../../../../common/Placeholder/Placeholder'
import {
  getFilterQueryParams,
  getTestProblemsArg,
  getTestProblemsWithPagingLocator,
} from '../TestProblems.utils'

import BatchActions from './BatchActions/BatchActions'
import TestProblemHeader from './TestProblemHeader/TestProblemHeader'
import TestProblemRow from './TestProblemRow/TestProblemRow'

import styles from './TestProblemList.module.css'

const PLACEHOLDER_LABEL = 'There are no tests found.'
const THROTTLER_TIMEOUT = 5000

type Props = {
  projectId?: ProjectId | null
  onlyInvestigated?: boolean
  selectedIds: TestId[]
  onSelectedIdsChange: (ids: TestId[]) => void
}

function TestProblemList({projectId, onlyInvestigated, selectedIds, onSelectedIdsChange}: Props) {
  const location = useLocation()
  const currentUser = useMyUsername()

  const hasPermissionForInvestigation = usePermission(Permission.ASSIGN_INVESTIGATION, projectId)
  const hasPermissionForMute = usePermission(Permission.MANAGE_BUILD_PROBLEMS, projectId)

  const {internalId: projectInternalId}: Partial<NormalizedProject> =
    useAppSelector(state => getProject(state, projectId)) ?? {}

  const filterQueryParams = getFilterQueryParams(location)
  const baseLocator = `affectedProject:${stringifyId(projectId)}`
  const locator = getTestProblemsWithPagingLocator(
    baseLocator,
    filterQueryParams,
    usePage(),
    onlyInvestigated,
    currentUser,
  )

  const pageSize = useAppSelector(state => getPager(state, PagerGroup.TEST_PROBLEM).pageSize)
  const arg = getTestProblemsArg(locator, pageSize)

  const {ids, isReady, isLoadingNewLocator, error, refetch} =
    restApi.endpoints.getAllTestProblemsNormalized.useQuery(arg, {
      selectFromResult: ({data, currentData, error}) => ({
        ids: data?.data.result ?? emptyArray,
        isReady: data != null,
        isLoadingNewLocator: data !== currentData,
        error,
      }),
    })
  const fetchTestProblemsWithThrottle = useThrottle(refetch, THROTTLER_TIMEOUT)

  useEffect(() => {
    if (projectInternalId != null) {
      return subscribeOnProjectEvents(
        projectInternalId,
        [TEST_RESPONSIBILITY_CHANGED, TEST_MUTE_UPDATED],
        fetchTestProblemsWithThrottle,
      )
    }
    return undefined
  }, [fetchTestProblemsWithThrottle, projectInternalId])

  const [expandedId, setExpandedId] = useQueryParamState('expandedProblem')

  const onToggleExpanded = useCallback(
    (id?: TestId | null | undefined) => {
      const idString = stringifyId(id)
      setExpandedId(expandedId === idString ? null : idString)
    },
    [expandedId, setExpandedId],
  )

  const onToggleSelected = useCallback(
    (id?: TestId) => {
      if (id != null) {
        onSelectedIdsChange(
          !selectedIds.includes(id) ? [...selectedIds, id] : selectedIds.filter(el => el !== id),
        )
      }
    },
    [onSelectedIdsChange, selectedIds],
  )

  const onToggleAllSelected = useCallback(() => {
    onSelectedIdsChange(selectedIds.length !== ids.length ? (ids as TestId[]) : [])
  }, [selectedIds, onSelectedIdsChange, ids])

  const onClearSelection = useCallback(() => {
    onSelectedIdsChange([])
  }, [onSelectedIdsChange])

  const onSaveMuteInvestigation = useCallback(() => {
    fetchTestProblemsWithThrottle()
    onSelectedIdsChange([])
  }, [fetchTestProblemsWithThrottle, onSelectedIdsChange])

  if (!isReady && !error) {
    return (
      <span>
        <LoaderInline>{'Loading...'}</LoaderInline>
      </span>
    )
  }

  if (error) {
    return <Placeholder message={PLACEHOLDER_LABEL} />
  }

  return (
    <>
      {!!ids.length && (
        <Grid className={classNames(styles.grid, {[styles.overlay]: isLoadingNewLocator})}>
          <TestProblemHeader
            withSelection={hasPermissionForInvestigation || hasPermissionForMute}
            count={ids.length}
            selectedCount={selectedIds.length}
            onToggleAllSelected={onToggleAllSelected}
          />
          <div className={styles.list}>
            <Suspense>
              {ids.map(id => (
                <TestProblemRow
                  key={id}
                  testId={id}
                  projectId={projectId}
                  projectInternalId={projectInternalId}
                  checked={selectedIds.includes(id!)}
                  expanded={expandedId === id}
                  onToggleSelected={onToggleSelected}
                  onToggleExpanded={onToggleExpanded}
                  onSaveMuteInvestigation={onSaveMuteInvestigation}
                />
              ))}
              <BatchActions
                projectId={projectId}
                selectedIds={selectedIds}
                onClear={onClearSelection}
                onSaveMuteInvestigation={onSaveMuteInvestigation}
              />
            </Suspense>
          </div>
        </Grid>
      )}
      <Pager
        group={PagerGroup.TEST_PROBLEM}
        warningComponent={TestProblemPagerWarning}
        isLoading={isLoadingNewLocator}
      />
    </>
  )
}

export default memo(TestProblemList)
