import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {memo} from 'react'
import {useLocation} from 'react-router'

import {useAppSelector} from '../../../../hooks/react-redux'
import {useMyUsername} from '../../../../hooks/useMyUsername'
import {useThrottle} from '../../../../hooks/useThrottle'
import {getProject} from '../../../../selectors'
import {restApi} from '../../../../services/rest'
import type {NormalizedProject, ProjectId} from '../../../../types'
import {stringifyId} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'
import {getFilterQueryParams} from '../TestProblems/TestProblems.utils'

import BuildProblemsProvider from './BuildProblems.context'
import {useBuildProblemsSubscriptions} from './BuildProblems.hooks'
import {getBuildProblemsArg, getBuildProblemsLocator} from './BuildProblems.rest'
import BuildProblemsTree from './BuildProblemsTree/BuildProblemsTree'

const THROTTLER_TIMEOUT = 5000

type Props = {
  projectId?: ProjectId
  onlyInvestigated?: boolean
}
function BuildProblems({projectId, onlyInvestigated}: Props) {
  const location = useLocation()
  const currentUser = useMyUsername()

  const filterQueryParams = getFilterQueryParams(location)
  const baseLocator = `affectedProject:${stringifyId(projectId)}`

  const {buildTypes}: Partial<NormalizedProject> =
    useAppSelector(state => getProject(state, projectId)) ?? {}

  const locator = getBuildProblemsLocator(
    baseLocator,
    filterQueryParams,
    onlyInvestigated,
    currentUser,
  )

  const arg = getBuildProblemsArg(locator)

  const {
    isReady,
    isLoadingNewLocator,
    refetch: refetchBuildProblemsTree,
  } = restApi.endpoints.getBuildProblemsTree.useQuery(arg, {
    selectFromResult: ({data, currentData, error}) => ({
      isReady: data != null || error,
      isLoadingNewLocator: data !== currentData,
    }),
  })

  const fetchBuildProblemsTreeHandler = useThrottle(refetchBuildProblemsTree, THROTTLER_TIMEOUT)

  useBuildProblemsSubscriptions({
    buildTypeIds: buildTypes?.buildType ?? emptyArray,
    handler: fetchBuildProblemsTreeHandler,
  })

  return isReady ? (
    <BuildProblemsProvider>
      <BuildProblemsTree
        projectId={projectId}
        locator={locator}
        arg={arg}
        onlyInvestigated={onlyInvestigated}
        isLoading={isLoadingNewLocator}
      />
    </BuildProblemsProvider>
  ) : (
    <span>
      <LoaderInline>{'Loading...'}</LoaderInline>
    </span>
  )
}
export default memo(BuildProblems)
