import type {ReactNode} from 'react'

export enum OrderDirection {
  ASC = 'asc',
  DESC = 'desc',
}
export type Column = {
  type: string
  name?: ReactNode | string
  withSorting?: boolean
  priorityOrder?: OrderDirection
  withCheckbox?: boolean
  checkboxTitle?: string
  className: string
}
export type OwnProps = {
  columns: Column[]
  rowsCount?: number
  selectedRowsCount?: number
  orderBy?: string
  order?: string
  onToggleSelection?: () => void
}

type HandlersProps = {
  onChangeQueryParams: (arg0: Record<string, string | null | undefined>) => unknown
}
export type Props = OwnProps & HandlersProps
