import type {BuildProblem} from '../../../../services/rest'
import type {ProblemsTreeNodeId, ProjectId} from '../../../../types'

export enum TreeEntityType {
  PROJECT = 'PROJECT',
  BUILD_TYPE = 'BUILD_TYPE',
  SPLIT_BUILD = 'SPLIT_BUILD',
}

type BuildProblems = {
  count?: number
  entry?: ReadonlyArray<BuildProblem>
}
type BaseBuildProblemsTreeLeaf<T> = {
  nodeId: ProblemsTreeNodeId
  problemEntries?: T
}
export type BuildProblemsTreeLeaf = BaseBuildProblemsTreeLeaf<BuildProblems>
export type BuildProblemsTreeNode = {
  id: ProblemsTreeNodeId
  parentId?: ProblemsTreeNodeId
  name: string
  childrenCount?: number
  problemCount?: number
  type: TreeEntityType
}
type BaseBuildProblemsTree<T> = {
  leaf?: ReadonlyArray<BaseBuildProblemsTreeLeaf<T>>
  node?: ReadonlyArray<BuildProblemsTreeNode>
}
export type BuildProblemsTree = BaseBuildProblemsTree<BuildProblems>

export type AdvancedNode = BuildProblemsTreeNode & {
  abstractParents?: Array<AdvancedNode>
  allParents?: Array<AdvancedNode>
  parentProjectLabel?: ProjectId | null
}
