import {memo, useCallback} from 'react'

import type {ProjectOrBuildTypeNode} from '../../../../types'
import {getProjectBuildTypeFilter} from '../../../../types'
import {ProjectBuildTypeSelect} from '../../../common/ProjectBuildTypeSelect/ProjectBuildTypeSelect'

import {useProjectIdFilter} from './ProjectBuildTypeFilter.hooks'

type Props = {
  onChange?: () => void
}
function ProjectBuildTypeFilter({onChange}: Props) {
  const {projectId, onProjectChange} = useProjectIdFilter()
  const onProjectSelect = useCallback(
    (data: ProjectOrBuildTypeNode | null | undefined) => {
      onProjectChange(data)
      onChange?.()
    },
    [onChange, onProjectChange],
  )

  return (
    <ProjectBuildTypeSelect
      allItemSelectable
      buttonMode
      expandAll
      allItemName="All projects"
      forceFetch={false}
      buildTypesSelectable={false}
      selected={getProjectBuildTypeFilter({projectId})}
      onSelect={onProjectSelect}
    />
  )
}

export default memo(ProjectBuildTypeFilter)
