import {memo, useCallback, Suspense} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../hooks/react-redux'
import type {ProjectId, TestId} from '../../../../types'
import FailedStatusFilter from '../../../common/FailedStatusFilter/FailedStatusFilter'
import InvestigationStatusFilter from '../../../common/InvestigationStatusFilter/InvestigationStatusFilter'
import MuteStatusFilter from '../../../common/MuteStatusFilter/MuteStatusFilter'
import ProjectBuildTypeFilter from '../ProjectBuildTypeFilter/ProjectBuildTypeFilter'

import TestProblemList from './TestProblemList/TestProblemList'
import {getSelectedTestProblems, setSelectedIds} from './TestProblems.selectors'

import styles from './TestProblems.module.css'

type Props = {
  projectId: ProjectId
  onlyInvestigated?: boolean
}
function TestProblems({projectId, onlyInvestigated}: Props) {
  const dispatch = useAppDispatch()

  const selectedIds = useAppSelector(state => getSelectedTestProblems(state))

  const onSelectedIdsChange = useCallback(
    (ids: TestId[]) => {
      dispatch(setSelectedIds(ids))
    },
    [dispatch],
  )

  const onClearSelection = useCallback(() => {
    dispatch(setSelectedIds([]))
  }, [dispatch])

  return (
    <>
      <div className={styles.row}>
        {onlyInvestigated && <ProjectBuildTypeFilter onChange={onClearSelection} />}
        <FailedStatusFilter onChange={onClearSelection} />
        {/*<GroupBy />*/}
        <MuteStatusFilter />
        {!onlyInvestigated && <InvestigationStatusFilter />}
      </div>
      <Suspense>
        <TestProblemList
          projectId={projectId}
          selectedIds={selectedIds}
          onSelectedIdsChange={onSelectedIdsChange}
          onlyInvestigated={onlyInvestigated}
        />
      </Suspense>
    </>
  )
}

export default memo(TestProblems)
