import {memo, Suspense, useCallback} from 'react'
import {useLocation} from 'react-router'

import {useQueryParamState} from '../../../hooks/routes'
import {queryToObject} from '../../../utils/queryParams'
import {UserProperties} from '../../../utils/userProperties'
import {useChangeProblemsFilter} from '../../packages/Problems/Problems.hooks'
import ModeSwitch, {Mode} from '../ModeSwitch/ModeSwitch'
import AllUserSelect from '../UserSelect/AllUserSelect'
import type {UserSelectSelectedItem} from '../UserSelect/UserSelect.types'

import {
  investigationFilterItems,
  InvestigationStatusFilter as InvestigationStatus,
} from './InvestigationStatusFilter.utils'

import styles from './InvestigationStatusFilter.module.css'

function InvestigationStatusFilter() {
  const location = useLocation()

  const selectedUser = queryToObject(location.search).assignee
  const onFilterChange = useChangeProblemsFilter()

  const [investigated] = useQueryParamState('investigated', InvestigationStatus.ALL)

  const onUsernameChange = useCallback(
    (item: UserSelectSelectedItem) => {
      onFilterChange({assignee: item?.value ?? ''})
    },
    [onFilterChange],
  )

  return (
    <div className={styles.container}>
      <ModeSwitch
        userProperty={UserProperties.PROBLEMS_INVESTIGATION_MODE}
        preserveParams={({mode, projectTab, currentlyFailing}) => ({
          projectTab,
          mode,
          currentlyFailing,
        })}
        param="investigated"
      >
        {investigationFilterItems.map(({key, label, value}) => (
          <Mode key={key} mode={value} label={label} />
        ))}
      </ModeSwitch>
      {investigated === 'true' && (
        <Suspense>
          <AllUserSelect
            label={'Assigned to'}
            selected={selectedUser}
            onChange={onUsernameChange}
          />
        </Suspense>
      )}
    </div>
  )
}
export default memo(InvestigationStatusFilter)
