import type {KeyValue} from '@jetbrains/teamcity-ui/dist/utils'
import {createSelector} from 'reselect'

import type {State} from '../../../../reducers/types'
import type {
  TestProblem,
  TestOccurrence,
  Investigation,
  Mute,
  BuildType,
} from '../../../../services/rest'
import type {ProblemOccurrenceId, TestId, TestOccurrenceId} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'

import {selectedTestProblems} from './TestProblems.slices'

const getTestProblems: (state: State) => KeyValue<TestId, TestProblem> = state =>
  state.entities.testProblems

export const getTestProblem: (state: State, id?: TestId) => TestProblem | undefined = (state, id) =>
  getTestProblems(state)[id!]

export const makeGetTestProblemsByTestIds: () => (
  state: State,
  ids: ReadonlyArray<TestId>,
) => ReadonlyArray<TestProblem> = () =>
  createSelector(
    [getTestProblems, (_: State, ids: ReadonlyArray<TestId>) => ids],
    (problems: KeyValue<TestId, TestProblem>, ids: ReadonlyArray<TestId>) =>
      ids.length > 0
        ? Object.values(problems).filter(
            problem => problem?.test?.id && ids?.includes(problem?.test?.id),
          )
        : emptyArray,
  )

const getTestProblemsFailingBuildTypesCount: (
  state: State,
) => KeyValue<TestId, number | null | undefined> = state =>
  state.entities.testProblemsFailingBuildTypesCount

export const getTestProblemFailingBuildTypesCount: (
  state: State,
  id?: TestId,
) => number | null | undefined = (state, id) => getTestProblemsFailingBuildTypesCount(state)[id!]

const getTestProblemsFailingBuildTypes: (
  state: State,
) => KeyValue<TestId, BuildType[] | null | undefined> = state =>
  state.entities.testProblemsFailingBuildTypes

export const getTestProblemFailingBuildTypes: (
  state: State,
  id?: TestId,
) => BuildType[] | null | undefined = (state, id) => getTestProblemsFailingBuildTypes(state)[id!]

const getTestOccurrencesHash: (
  state: State,
) => KeyValue<TestOccurrenceId, TestOccurrence> = state => state.entities.testProblemTestOccurrences

export const makeGetTestOccurrencesList: () => (
  state: State,
  ids: ReadonlyArray<TestOccurrenceId>,
) => {
  currentFailures: ReadonlyArray<TestOccurrence>
  firstFailures: ReadonlyArray<TestOccurrence>
} = () =>
  createSelector(
    [(_: State, ids: ReadonlyArray<TestOccurrenceId>) => ids, getTestOccurrencesHash],
    (
      ids: ReadonlyArray<TestOccurrenceId>,
      testOccurrences: KeyValue<TestOccurrenceId, TestOccurrence>,
    ) => ({
      currentFailures:
        ids.length > 0
          ? ids.map((id: TestOccurrenceId) => testOccurrences[id]).filter(Boolean)
          : emptyArray,
      firstFailures:
        ids.length > 0
          ? ids
              .map(
                (id: TestOccurrenceId) => testOccurrences[id]?.firstFailed ?? testOccurrences[id],
              )
              .filter(Boolean)
          : emptyArray,
    }),
  )

const getTestProblemsMutes: (state: State) => KeyValue<TestId, ReadonlyArray<Mute>> = state =>
  state.entities.testProblemsMutes

export const getTestProblemMutes: (state: State, id?: TestId) => ReadonlyArray<Mute> | undefined = (
  state,
  id,
) => getTestProblemsMutes(state)[id!]

const getTestProblemsInvestigations: (
  state: State,
) => KeyValue<TestId, ReadonlyArray<Investigation>> = state =>
  state.entities.testProblemsInvestigations

export const getTestProblemInvestigations: (
  state: State,
  id?: TestId,
) => ReadonlyArray<Investigation> | undefined = (state, id) =>
  getTestProblemsInvestigations(state)[id!]

export const getSelectedTestProblems: (state: State) => ProblemOccurrenceId[] = state =>
  state.selectedTestProblems.selectedIds

export const setSelectedIds = selectedTestProblems.actions.setSelectedIds
