import {useCallback} from 'react'
import {useLocation} from 'react-router'

import type {ProjectOrBuildTypeNode} from '../../../../types'
import {toProjectId} from '../../../../types'
import {queryToObject} from '../../../../utils/queryParams'
import {useChangeProblemsFilter} from '../Problems.hooks'

export const useProjectIdFilter = () => {
  const location = useLocation()
  const {projectId} = queryToObject(location.search)
  const onFilterChange = useChangeProblemsFilter()
  const onProjectChange = useCallback(
    (data: ProjectOrBuildTypeNode | null | undefined) => {
      if (data?.nodeType === 'project') {
        onFilterChange({projectId: data?.id || undefined})
      } else {
        onFilterChange({projectId: undefined})
      }
    },
    [onFilterChange],
  )
  return {
    projectId: projectId != null ? toProjectId(projectId) : null,
    onProjectChange,
  }
}
