import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import type {SyntheticEvent} from 'react'
import {memo, Suspense, useCallback, useId, useMemo} from 'react'

import {useAppSelector} from '../../../../../../hooks/react-redux'
import {usePermission} from '../../../../../../hooks/usePermission'
import {useHeightResizeObserver} from '../../../../../../hooks/useResizeObserver'
import type {ProjectId, ProjectInternalId, TestId} from '../../../../../../types'
import {Permission} from '../../../../../../types'
import {TestInvestigationHistoryPopupDummy} from '../../../../InvestigationHistory/TestInvestigationHistoryPopup/TestInvestigationHistoryPopup'
import TableRow from '../../../TableRow/TableRow'
import {getTestProblem, getTestProblemFailingBuildTypesCount} from '../../TestProblems.selectors'

import Failures from './Failures/Failures'
import TestActions from './TestActions/TestActions'
import TestFailures from './TestFailures/TestFailures'
import TestInvestigations from './TestInvestigations/TestInvestigations'
import TestName from './TestName/TestName'
import {getTestNames} from './TestName/TestName.utils'
import TestStatus from './TestStatus/TestStatus'

import styles from './TestProblemRow.module.css'

type Props = {
  projectId?: ProjectId | null
  projectInternalId?: ProjectInternalId | null
  testId?: TestId
  checked?: boolean
  expanded?: boolean
  onToggleSelected: (id: TestId) => void
  onToggleExpanded: (id?: TestId | null) => void
  onSaveMuteInvestigation: () => void
}

function TestProblemRow({
  projectId,
  projectInternalId,
  testId,
  checked,
  expanded,
  onToggleSelected,
  onToggleExpanded,
  onSaveMuteInvestigation,
}: Props) {
  const hasPermissionForInvestigation = usePermission(Permission.ASSIGN_INVESTIGATION, projectId)
  const hasPermissionForMute = usePermission(Permission.MANAGE_BUILD_PROBLEMS, projectId)

  const entry = useAppSelector(state => getTestProblem(state, testId))
  const {name} = getTestNames(entry?.test?.parsedTestName ?? {})

  const failuresCount =
    useAppSelector(state => getTestProblemFailingBuildTypesCount(state, testId)) ?? 0
  const [innerHeight, measureRef] = useHeightResizeObserver()

  const toggleSelect = useCallback(
    (event: SyntheticEvent) => {
      event.stopPropagation()
      if (testId) {
        onToggleSelected(testId)
      }
    },
    [onToggleSelected, testId],
  )

  const toggleExpand = useCallback(() => {
    if (testId) {
      onToggleExpanded(testId)
    }
  }, [onToggleExpanded, testId])

  const nameColumnId = useId()

  const renderRowGroup = useMemo(
    () => (
      <>
        <div className={styles.statusColumn}>
          {(hasPermissionForInvestigation || hasPermissionForMute) && (
            <Checkbox aria-labelledby={nameColumnId} checked={checked} onChange={toggleSelect} />
          )}
          <TestStatus testId={testId} />
        </div>

        <div id={nameColumnId} className={styles.testNameColumn}>
          <TestName testId={testId} full={expanded} />
        </div>

        <div className={styles.failuresColumn}>
          <TestFailures testId={testId} expanded={expanded} onClick={toggleExpand} />
        </div>

        <div className={styles.assignedColumn}>
          <TestInvestigations testId={testId} expanded={expanded} onToggle={toggleExpand} />
        </div>

        <div className={styles.actionsColumn}>
          <Suspense>
            <TestActions
              testId={testId}
              projectId={projectId}
              onSaveMuteInvestigation={onSaveMuteInvestigation}
            />
          </Suspense>
        </div>
      </>
    ),
    [
      hasPermissionForInvestigation,
      hasPermissionForMute,
      nameColumnId,
      checked,
      toggleSelect,
      testId,
      expanded,
      toggleExpand,
      projectId,
      onSaveMuteInvestigation,
    ],
  )

  return (
    <>
      <TableRow
        expanded={expanded}
        label={`Problem ${testId}`}
        onToggleExpanded={toggleExpand}
        summary={renderRowGroup}
      >
        <div style={{height: innerHeight}} className={styles.outerContainer}>
          <div ref={measureRef} className={styles.innerContainer}>
            {failuresCount > 0 && <Failures projectId={projectId} testId={testId} />}
          </div>
        </div>
      </TableRow>
      <TestInvestigationHistoryPopupDummy
        testId={testId}
        testName={name}
        projectId={projectId}
        projectInternalId={projectInternalId}
      />
    </>
  )
}

export default memo(TestProblemRow)
