import Button from '@jetbrains/ring-ui-built/components/button/button'
import {memo} from 'react'

import {useAppSelector} from '../../../../../../../hooks/react-redux'
import type {TestId} from '../../../../../../../types'
import Icon from '../../../../../../common/Icon/Icon'
import {
  getTestProblemFailingBuildTypes,
  getTestProblemFailingBuildTypesCount,
} from '../../../TestProblems.selectors'

import styles from './TestFailures.module.css'

const NO_RECENT_FAILURES = 'no recent failures'

type TestFailuresProps = {
  testId?: TestId
  expanded?: boolean
  onClick?: () => void
}
function TestFailures({testId, expanded, onClick}: TestFailuresProps) {
  const buildTypes = useAppSelector(state => getTestProblemFailingBuildTypes(state, testId))
  const buildTypesCount =
    useAppSelector(state => getTestProblemFailingBuildTypesCount(state, testId)) ?? 0

  if (!buildTypesCount) {
    return <div className={styles.noFailures}>{NO_RECENT_FAILURES}</div>
  }

  const oneBuildType = buildTypesCount === 1
  const failures = oneBuildType ? '1 failure in' : `${buildTypesCount} failures in`
  const configurations = oneBuildType ? buildTypes?.[0].name : `${buildTypesCount} configurations`

  return (
    <div className={styles.container}>
      <div className={styles.status}>{failures}</div>
      <div className={styles.configuration}>
        <Button
          inline
          className={styles.configurationButton}
          title={expanded ? 'Collapse' : 'Expand'}
          onClick={onClick}
        >
          <span className={styles.configurationContent}>
            <span className={styles.configurationText}>{configurations}</span>
            <Icon className={styles.arrow} name={expanded ? 'chevron-up' : 'chevron-down'} />
          </span>
        </Button>
      </div>
    </div>
  )
}

export default memo(TestFailures)
