import {memo, useMemo} from 'react'

import RowGroup from '../../../../../common/Grid/RowGroup'
import TableHeader from '../../../TableHeader/TableHeader.container'
import type {Column} from '../../../TableHeader/TableHeader.types'

import {OrderByField} from './BuildProblemHeader.types'

import styles from './BuildProblemHeader.module.css'

type Props = {
  count: number
  selectedCount: number
  compact?: boolean
  onToggleAllSelected?: () => void
}

function BuildProblemHeader({count, selectedCount, compact, onToggleAllSelected}: Props) {
  const columns: Column[] = useMemo(
    () => [
      {
        type: 'status',
        withCheckbox: true,
        checkboxTitle: 'Select all build problems',
        className: styles.statusColumn,
      },
      {
        type: OrderByField.BUILD,
        name: 'Build',
        className: styles.buildColumn,
      },
      {
        type: OrderByField.PROBLEM_NAME,
        name: 'Problem name / Status',
        className: styles.problemNameColumn,
      },
      {
        type: OrderByField.CHANGES,
        name: compact ? (
          <>
            {'Changes'} <br /> {'Assigned by / Assignee / Comment'}
          </>
        ) : (
          'Changes'
        ),
        className: styles.changesColumn,
      },
      ...(!compact
        ? [
            {
              type: OrderByField.ASSIGNMENT,
              name: 'Assigned by / Assignee / Comment',
              className: styles.assignedColumn,
            },
          ]
        : []),
      {
        type: 'actions',
        className: styles.actionsColumn,
      },
    ],
    [compact],
  )

  return (
    <RowGroup span={1}>
      <TableHeader
        rowsCount={count}
        selectedRowsCount={selectedCount}
        columns={columns}
        onToggleSelection={onToggleAllSelected}
      />
    </RowGroup>
  )
}

export default memo(BuildProblemHeader)
