import type {ParsedTestName} from '../../../../../../../services/rest'
import {trimAndRemoveColon} from '../../../../../Tests/Tests.utils'

export function getTestNames(parsedTestName: ParsedTestName) {
  const {testClass, testNameWithParameters, testSuite, testPackage} = parsedTestName
  const formattedTestSuiteAndPackage = testPackage
    ? `${testSuite}${testPackage}`
    : trimAndRemoveColon(testSuite ?? '')

  return {
    name: testClass ? `${testClass}.${testNameWithParameters}` : testNameWithParameters,
    suiteAndPackage: formattedTestSuiteAndPackage,
  }
}
