import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import {memo, useCallback} from 'react'
import {useLocation} from 'react-router'

import {useChangeProblemsFilter} from '../../packages/Problems/Problems.hooks'

import {
  failedFilterItems,
  FailedStatusFilter as FailedStatus,
  getFailedStatusQueryParam,
} from './FailedStatusFilter.utils'

import styles from './FailedStatusFilter.module.css'

type Props = {
  onChange?: () => void
}
function FailedStatusFilter({onChange}: Props) {
  const location = useLocation()
  const failed = getFailedStatusQueryParam(location)

  const onFilterChange = useChangeProblemsFilter()

  const onFailedStatusChange = useCallback(
    (key: string) => {
      const value = key === FailedStatus.FAILED ? null : FailedStatus.ALL
      onFilterChange({currentlyFailing: value})
      onChange?.()
    },
    [onChange, onFilterChange],
  )

  return (
    <div className={styles.container}>
      <ButtonGroup>
        {failedFilterItems.map(({key, label}) => (
          <Button key={key} active={failed === key} onClick={() => onFailedStatusChange(key)}>
            {label}
          </Button>
        ))}
      </ButtonGroup>
    </div>
  )
}
export default memo(FailedStatusFilter)
