import type {Location} from 'history'

import type {
  GetAllTestOccurrencesNormalizedApiArg,
  GetAllTestProblemsNormalizedApiArg,
} from '../../../../services/rest'
import {isValue} from '../../../../utils/guards'
import {queryToObject} from '../../../../utils/queryParams'
import type {FilterQueryParams} from '../Problems.hooks'
import {OrderDirection} from '../TableHeader/TableHeader.types'

const COUNT_PROBLEMS = 25
const COUNT_TEST_OCCURRENCES = 10

export enum OrderByField {
  STATUS = 'status',
  NAME = 'testName',
  FAILURE_COUNT = 'failureCount',
  ASSIGNMENT = 'assignment',
  NEW_FAILURE = 'newFailure',
}

export const getFilterQueryParams = (location: Location): FilterQueryParams => {
  const {
    order,
    orderBy,
    investigated = 'all',
    muted = 'all',
    assignee,
    currentlyFailing,
  } = queryToObject(location?.search)
  return {
    orderBy: isValue(OrderByField, orderBy) ? orderBy : OrderByField.NEW_FAILURE,
    order: isValue(OrderDirection, order) ? order : OrderDirection.DESC,
    investigated,
    muted,
    assignee,
    currentlyFailing,
  }
}

export const getTestProblemOccurrencesLocator = (baseLocator: string, start?: number) => {
  const locator = 'orderBy:(newFailure:desc)'
  const countLocator = `count:${COUNT_TEST_OCCURRENCES}`
  const startLocator = start != null ? `start:${(start - 1) * COUNT_TEST_OCCURRENCES}` : ''
  return [baseLocator, locator, countLocator, startLocator].filter(Boolean).join(',')
}

export const getTestProblemsWithPagingLocator = (
  baseLocator: string,
  {investigated, order, orderBy, muted, assignee, currentlyFailing}: FilterQueryParams,
  currentPage?: number,
  onlyInvestigated = false,
  currentUser?: string | null,
) => {
  let investigatedLocator = investigated ? `currentlyInvestigated:${investigated}` : ''
  let assigneeLocator = assignee ? `assignee:${assignee}` : ''

  const orderLocator = orderBy && order ? `orderBy:(${orderBy}:${order})` : ''
  const mutedLocator = muted ? `currentlyMuted:${muted}` : ''
  if (onlyInvestigated) {
    investigatedLocator = 'currentlyInvestigated:true'
    assigneeLocator = `assignee:${currentUser}`
  }
  const currentlyFailingLocator = `currentlyFailing:${currentlyFailing === 'all' ? 'any' : 'true'}`

  const countLocator = `count:${COUNT_PROBLEMS}`
  const startLocator = currentPage != null ? `start:${(currentPage - 1) * COUNT_PROBLEMS}` : ''
  return [
    baseLocator,
    investigatedLocator,
    mutedLocator,
    assigneeLocator,
    currentlyFailingLocator,
    orderLocator,
    countLocator,
    startLocator,
  ]
    .filter(Boolean)
    .join(',')
}

export const getTestProblemsArg = (
  locator: string,
  pageSize: number,
): GetAllTestProblemsNormalizedApiArg => ({
  locator,
  fields: `count,nextHref,entry(test(id,name,parsedTestName),mutes(count,mute(*,assignment(*,user(*)),scope(*,buildTypes(*)),target(tests(test)))),investigations(count,investigation(*,assignment(*,user(*)),scope(*,buildTypes(*)))),failingBuildTypes(count,buildType(id,name)))`,
  pageSize,
})

export const getTestProblemOccurrencesArg = (
  locator: string,
): GetAllTestOccurrencesNormalizedApiArg => {
  const buildArg =
    'build(id,buildTypeId,startDate,number,defaultBranch,branchName,limitedChangesCount,history,state,buildType(id,project))'
  return {
    locator,
    fields: `count,nextHref,testOccurrence(id,name,${buildArg},status,muted,logAnchor,firstFailed(id,name,${buildArg},status,metadata))`,
  }
}
