import List from '@jetbrains/ring-ui-built/components/list/list'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {memo, useCallback} from 'react'
import {useLocation, useNavigate} from 'react-router'

import {getHrefWithQueryParams} from '../../../../../../../../../routes'
import type {TestOccurrence} from '../../../../../../../../../services/rest'
import {stringifyId} from '../../../../../../../../../types'
import {BS} from '../../../../../../../../../types/BS_types'
import ArrowPopupMenu from '../../../../../../../../common/ArrowPopupMenu/ArrowPopupMenu'
import {getFullBuildLogLinkParams} from '../../../../../../../BuildLog/BuildLog.utils'
import TestMetadataIcon from '../../../../../../../Tests/TestMetadataIcon/TestMetadataIcon'
import {TestStatus} from '../../../../../../../Tests/Tests.types'

import styles from './FailureActions.module.css'

type Props = {
  testOccurrence?: TestOccurrence
}

function FailureActions({testOccurrence}: Props) {
  const location = useLocation()
  const navigate = useNavigate()

  const {id, status, metadata, logAnchor, build} = testOccurrence ?? {}
  const buildId = build?.id

  const onBuildLogOpen = useCallback(() => {
    if (buildId) {
      navigate(
        getHrefWithQueryParams(location, null, params => ({
          ...params,
          ...getFullBuildLogLinkParams({
            buildId,
            line: logAnchor,
            expandState: [Number(logAnchor)],
            logFilter: 'debug',
          }),
        })),
        {preventScrollReset: true},
      )
    }
  }, [buildId, location, logAnchor, navigate])

  const onOpenInIDE = useCallback(
    () =>
      logAnchor != null &&
      BS?.Activator?.doOpen(`test?buildId=${stringifyId(buildId)}&testId=${logAnchor}`),
    [logAnchor, buildId],
  )

  const elements = []
  if (status === TestStatus.FAILURE && logAnchor != null) {
    elements.push({
      rgItemType: List.ListProps.Type.ITEM,
      title: '',
      label: 'Open in IDE',
      onClick: onOpenInIDE,
    })
  }

  return (
    <>
      <TestMetadataIcon testOccurrenceId={id} metadataCount={metadata?.count ?? 0} />
      <IconButton title="Show in Build Log" icon="file" onClick={onBuildLogOpen} />
      {!!elements.length && <ArrowPopupMenu className={styles.menu} elements={elements} />}
    </>
  )
}
export default memo(FailureActions)
