import type {Location} from 'react-router'

import {queryToObject} from '../../../utils/queryParams'

export enum FailedStatusFilter {
  ALL = 'all',
  FAILED = 'failed',
}
type FailedFilter = {
  key: FailedStatusFilter
  label: string
}
export const failedFilterItems: FailedFilter[] = [
  {key: FailedStatusFilter.ALL, label: 'All'},
  {key: FailedStatusFilter.FAILED, label: 'Failed'},
]

export const getFailedStatusQueryParam = (location: Location): FailedStatusFilter => {
  const {currentlyFailing} = queryToObject(location.search)
  return currentlyFailing === FailedStatusFilter.ALL
    ? FailedStatusFilter.ALL
    : FailedStatusFilter.FAILED
}
