import classNames from 'classnames'
import {memo, useCallback, useMemo} from 'react'

import {useQueryParamState} from '../../../../../hooks/routes'
import type {BuildProblem} from '../../../../../services/rest'
import type {ProblemOccurrenceId, ProjectId} from '../../../../../types'
import {stringifyId} from '../../../../../types'
import Grid from '../../../../common/Grid/Grid'
import {useWidthResize} from '../BuildProblems.context'

import BuildProblemHeader from './BuildProblemHeader/BuildProblemHeader'
import BuildProblemRow from './BuildProblemRow/BuildProblemRow'

import styles from './BuildProblemList.module.css'

const WIDTH_LIMIT = 1000

type Props = {
  projectId?: ProjectId | null
  buildProblems: ReadonlyArray<BuildProblem>
  selectedIds: ProblemOccurrenceId[]
  onSelectedIdsChange: (ids: ProblemOccurrenceId[]) => void
  onSaveMuteInvestigation: () => void
}

function BuildProblemList({
  projectId,
  buildProblems,
  selectedIds,
  onSelectedIdsChange,
  onSaveMuteInvestigation,
}: Props) {
  const [expandedId, setExpandedId] = useQueryParamState('expandedProblem')
  const {width} = useWidthResize()
  const compact = !!width && width < WIDTH_LIMIT

  const ids = useMemo(
    () =>
      buildProblems
        ?.map(buildProblem => buildProblem?.problemOccurrence?.id ?? '')
        .filter(Boolean) ?? [],
    [buildProblems],
  )

  const currentSelectedIds = useMemo(
    () => selectedIds.filter(value => ids.includes(value)),
    [ids, selectedIds],
  )

  const onToggleExpanded = useCallback(
    (id?: ProblemOccurrenceId | null | undefined) => {
      const idString = stringifyId(id)
      setExpandedId(expandedId === idString ? null : idString)
    },
    [expandedId, setExpandedId],
  )

  const onToggleSelected = useCallback(
    (id?: ProblemOccurrenceId) => {
      if (id != null) {
        const updatedIds = !selectedIds.includes(id)
          ? [...selectedIds, id]
          : selectedIds.filter(value => value !== id)
        onSelectedIdsChange?.(updatedIds)
      }
    },
    [onSelectedIdsChange, selectedIds],
  )

  const onToggleAllSelected = useCallback(() => {
    const nonSelected = ids.filter(value => !selectedIds.includes(value))
    const updatedIds =
      nonSelected.length === 0
        ? selectedIds.filter(value => !ids.includes(value))
        : [...selectedIds, ...nonSelected]
    onSelectedIdsChange?.(updatedIds)
  }, [ids, onSelectedIdsChange, selectedIds])

  if (!ids.length) {
    return null
  }

  return (
    <Grid className={classNames(styles.grid, {[styles.compact]: compact})}>
      <BuildProblemHeader
        count={ids.length}
        selectedCount={currentSelectedIds.length}
        compact={compact}
        onToggleAllSelected={onToggleAllSelected}
      />
      <div className={styles.list}>
        {ids?.map(id => (
          <BuildProblemRow
            projectId={projectId}
            key={id}
            buildProblemId={id}
            compact={compact}
            checked={currentSelectedIds.includes(id)}
            expanded={expandedId === id}
            onToggleSelected={onToggleSelected}
            onToggleExpanded={onToggleExpanded}
            onSaveMuteInvestigation={onSaveMuteInvestigation}
          />
        ))}
      </div>
    </Grid>
  )
}

export default memo(BuildProblemList)
