import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {ReactNode} from 'react'
import {useMemo} from 'react'

import Details from '../../../common/Details/Details'
import RowGroup from '../../../common/Grid/RowGroup'

import styles from './TableRow.module.css'

type Props = {
  label: string
  summaryClassName?: string
  containerClassName?: string
  expanded?: boolean
  summary: ReactNode
  onToggleExpanded?: (value: boolean) => void
  children?: ReactNode
}

function TableRow({
  label,
  summaryClassName,
  containerClassName,
  expanded,
  summary,
  onToggleExpanded,
  children,
}: Props) {
  const renderSummary = useMemo(
    () => (
      <>
        <div className={styles.row}>{summary}</div>
        <SvgIcon className={styles.arrow} icon={expanded ? 'chevron-up' : 'chevron-down'} />
      </>
    ),
    [expanded, summary],
  )

  return (
    <RowGroup span={2}>
      <div
        className={classNames(styles.details, containerClassName, {
          [styles.expanded]: expanded,
        })}
      >
        <Details
          imitateHeading
          renderButtonAside
          level={2}
          headingClassName={styles.details}
          summaryClassName={classNames(styles.button, summaryClassName)}
          detailsWrapperClassName={styles.detailsWrapper}
          summary={renderSummary}
          label={label}
          open={expanded}
          onToggle={onToggleExpanded}
        >
          {children}
        </Details>
      </div>
    </RowGroup>
  )
}
export default TableRow
