import {withHandlers} from 'recompose'

import compose from 'lodash/flowRight'
import type {ComponentType} from 'react'
import {memo} from 'react'

import type {LocationProps} from '../../../../routes'
import {getHrefWithQueryParams, withLocation} from '../../../../routes'

import TableHeader from './TableHeader'
import type {OwnProps} from './TableHeader.types'

const TableHeaderContainer: ComponentType<OwnProps> = compose(
  memo,
  withLocation,
  withHandlers({
    onChangeQueryParams:
      ({location, navigate}: LocationProps) =>
      (newParams: Record<string, string | null | undefined>) =>
        navigate(
          getHrefWithQueryParams(location, null, oldParams => ({...oldParams, ...newParams})),
          {preventScrollReset: true},
        ),
  }),
)(TableHeader)
export default TableHeaderContainer
