import type {ReactNode, Ref} from 'react'
import {createContext, memo, useContext} from 'react'

import {useWidthResizeObserver} from '../../../../hooks/useResizeObserver'

type Props = {width?: number; ref: Ref<HTMLDivElement>}
const BuildProblemsContext = createContext<Props>({} as Props)
function BuildProblemsProvider({children}: {children: ReactNode}) {
  const [width, ref] = useWidthResizeObserver()

  return (
    <BuildProblemsContext.Provider value={{width, ref}}>{children}</BuildProblemsContext.Provider>
  )
}
export default memo(BuildProblemsProvider)

export const useWidthResize = (): Props => useContext(BuildProblemsContext)
