import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import plur from 'plur'
import {memo, useCallback, useState} from 'react'

import {openDialog} from '../../../../../../../actions'
import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import type {BuildId, ProblemOccurrenceId} from '../../../../../../../types'
import {DialogType, stringifyId} from '../../../../../../../types'
import BuildPathAndStatus from '../../../../../../common/BuildPathAndStatus/BuildPathAndStatus'
import {getKeyForBuildLogData} from '../../../../../BuildLog/BuildLog.utils'
import BuildLogPreview from '../../../../../BuildLog/BuildLogPreview/BuildLogPreview.container'
import {getBuildProblem} from '../../../BuildProblems.selectors'

import styles from './BuildProblemDetails.module.css'

enum ProblemDetailsTab {
  BUILD_LOG = 'Build log',
  ALSO_IN = 'Also in',
}

type Props = {
  buildId?: BuildId | null
  buildProblemId: ProblemOccurrenceId
}
function BuildProblemDetails({buildId, buildProblemId}: Props) {
  const dispatch = useAppDispatch()
  const logAnchor = useAppSelector(
    state => getBuildProblem(state, buildProblemId)?.problemOccurrence?.logAnchor ?? 0,
  )
  const alsoInBuilds = useAppSelector(
    state => getBuildProblem(state, buildProblemId)?.alsoIn?.build,
  )

  const onShowInvestigationHistory = useCallback(
    () => dispatch(openDialog(stringifyId(buildProblemId), DialogType.INVESTIGATION_HISTORY)),
    [dispatch, buildProblemId],
  )

  const [activeTab, setActiveTab] = useState(ProblemDetailsTab.BUILD_LOG)

  const onBuildLogTabClick = useCallback(() => {
    setActiveTab(ProblemDetailsTab.BUILD_LOG)
  }, [])

  const onAlsoInTabClick = useCallback(() => {
    setActiveTab(ProblemDetailsTab.ALSO_IN)
  }, [])

  return (
    <>
      <div className={styles.links}>
        <Button
          inline
          className={styles.linkButton}
          height={ControlsHeight.S}
          onClick={onShowInvestigationHistory}
        >
          {'Investigation history'}
        </Button>
      </div>
      {!!alsoInBuilds?.length && (
        <ButtonGroup className={styles.tabs}>
          <Button active={activeTab === ProblemDetailsTab.BUILD_LOG} onClick={onBuildLogTabClick}>
            {ProblemDetailsTab.BUILD_LOG}
          </Button>
          <Button active={activeTab === ProblemDetailsTab.ALSO_IN} onClick={onAlsoInTabClick}>
            {`Also reported in ${alsoInBuilds?.length} more build ${plur('configuration', alsoInBuilds?.length)} `}
          </Button>
        </ButtonGroup>
      )}
      {activeTab === ProblemDetailsTab.BUILD_LOG ? (
        buildId != null && logAnchor != null ? (
          <div className={styles.log}>
            <BuildLogPreview
              buildId={buildId}
              problemOccurrenceId={buildProblemId}
              focusLine={logAnchor}
              expandLine={logAnchor}
              buildLogKey={getKeyForBuildLogData({type: 'problem', id: buildProblemId})}
              withLoadingData
            />
          </div>
        ) : null
      ) : (
        <div className={styles.buildPathContainer}>
          {alsoInBuilds?.map(build => (
            <BuildPathAndStatus
              key={build.id}
              buildTypeId={build?.buildTypeId}
              buildId={build.id}
              withLeafStatusIcon={false}
              withIcon={false}
              className={styles.buildPathAndStatus}
              buildStatusClassName={styles.buildStatus}
              buildPathClassName={styles.buildPath}
            />
          ))}
        </div>
      )}
    </>
  )
}

export default memo(BuildProblemDetails)
