import Button from '@jetbrains/ring-ui-built/components/button/button'
import List from '@jetbrains/ring-ui-built/components/list/list'
import {memo, useCallback, useMemo} from 'react'
import {useLocation, useNavigate} from 'react-router'

import {assignProblemInvestigations, openDialog} from '../../../../../../../actions'
import {useAppDispatch} from '../../../../../../../hooks/react-redux'
import {usePermission} from '../../../../../../../hooks/usePermission'
import {getHrefWithQueryParams} from '../../../../../../../routes'
import {DialogType, Permission, stringifyId} from '../../../../../../../types'
import ArrowPopupMenu from '../../../../../../common/ArrowPopupMenu/ArrowPopupMenu'
import {getFullBuildLogLinkParams} from '../../../../../BuildLog/BuildLog.utils'

import type {Props} from './BuildProblemActions.types'

import styles from './BuildProblemActions.module.css'

function BuildProblemActions({
  buildProblemId,
  projectId,
  buildId,
  targetId,
  logAnchor,
  mutes,
  investigations,
  onSaveMuteInvestigation,
}: Props) {
  const dispatch = useAppDispatch()
  const location = useLocation()
  const navigate = useNavigate()

  const hasPermissionForInvestigation = usePermission(Permission.ASSIGN_INVESTIGATION, projectId)
  const hasPermissionForMute = usePermission(Permission.MANAGE_BUILD_PROBLEMS, projectId)

  const currentlyMuted = !!mutes?.length
  const currentlyInvestigated = !!investigations?.length

  const onMute = useCallback(() => {
    dispatch(assignProblemInvestigations(targetId, buildId, false, onSaveMuteInvestigation))
  }, [dispatch, targetId, buildId, onSaveMuteInvestigation])

  const onInvestigate = useCallback(() => {
    dispatch(assignProblemInvestigations(targetId, buildId, false, onSaveMuteInvestigation))
  }, [dispatch, targetId, buildId, onSaveMuteInvestigation])

  const onFix = useCallback(() => {
    dispatch(assignProblemInvestigations(targetId, buildId, true, onSaveMuteInvestigation))
  }, [dispatch, targetId, buildId, onSaveMuteInvestigation])

  const onShowInBuildLog = useCallback(
    () =>
      buildId != null
        ? navigate(
            getHrefWithQueryParams(location, null, params => ({
              ...params,
              ...getFullBuildLogLinkParams({
                buildId,
                line: logAnchor,
                expandState: [Number(logAnchor)],
                logFilter: 'debug',
              }),
            })),
            {preventScrollReset: true},
          )
        : null,
    [buildId, location, logAnchor, navigate],
  )

  const onShowInvestigationHistory = useCallback(() => {
    dispatch(openDialog(stringifyId(buildProblemId), DialogType.INVESTIGATION_HISTORY))
  }, [dispatch, buildProblemId])

  const elements = useMemo(() => {
    const result = []
    if (hasPermissionForInvestigation) {
      if (currentlyInvestigated) {
        result.push({
          rgItemType: List.ListProps.Type.ITEM,
          label: 'Mark as Fixed Problem',
          onClick: onFix,
        })
      }
      result.push({
        rgItemType: List.ListProps.Type.ITEM,
        label: currentlyInvestigated ? 'Reassign Investigation...' : 'Assign Investigation...',
        onClick: onInvestigate,
      })
    }

    result.push({
      rgItemType: List.ListProps.Type.ITEM,
      label: 'Show Investigation History',
      onClick: onShowInvestigationHistory,
    })
    result.push({
      rgItemType: List.ListProps.Type.ITEM,
      label: 'Show in Build Log',
      onClick: onShowInBuildLog,
    })
    return result
  }, [
    currentlyInvestigated,
    hasPermissionForInvestigation,
    onFix,
    onInvestigate,
    onShowInBuildLog,
    onShowInvestigationHistory,
  ])

  return (
    <div className={styles.container}>
      {hasPermissionForMute && (
        <Button onClick={onMute}>{currentlyMuted ? 'Unmute' : 'Mute'}</Button>
      )}
      {hasPermissionForInvestigation && <Button onClick={onInvestigate}>{'Investigate'}</Button>}
      <ArrowPopupMenu className={styles.menu} elements={elements} />
    </div>
  )
}
export default memo(BuildProblemActions)
