import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {memo, useCallback, useEffect, useMemo, useState} from 'react'
import {shallowEqual} from 'react-redux'
import {useNavigate} from 'react-router'

import {openDialog} from '../../../../../../../actions'
import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {getTestHistoryHref} from '../../../../../../../routes'
import type {TestOccurrence} from '../../../../../../../services/rest'
import {restApi} from '../../../../../../../services/rest'
import {DialogType, stringifyId} from '../../../../../../../types'
import type {ProjectId, TestId} from '../../../../../../../types'
import {emptyArray} from '../../../../../../../utils/empty'
import Grid from '../../../../../../common/Grid/Grid'
import RowGroup from '../../../../../../common/Grid/RowGroup'
import {makeGetTestOccurrencesList} from '../../../TestProblems.selectors'
import {
  getTestProblemOccurrencesArg,
  getTestProblemOccurrencesLocator,
} from '../../../TestProblems.utils'

import DetailedTestHeader from './FailureHeader/FailureHeader'
import FailureRow from './FailureRow/FailureRow'

import styles from './Failures.module.css'

enum FailureTab {
  CURRENT_FAILURE = 'Current failures',
  FIRST_FAILURE = 'First failures',
}

type Props = {
  projectId?: ProjectId | null
  testId?: TestId
}
function Failures({projectId, testId}: Props) {
  const navigate = useNavigate()
  const dispatch = useAppDispatch()

  const [start, setStart] = useState(1)
  const baseLocator = `affectedProject:${stringifyId(
    projectId,
  )},test:(id:${testId}),currentlyFailing:true,investigationState:none,investigationState:active,investigationState:givenUp`
  const locator = getTestProblemOccurrencesLocator(baseLocator, start)
  const arg = getTestProblemOccurrencesArg(locator)
  const [occurrenceIds, setOccurrenceIds] = useState<string[]>([])
  const {ids, isLoading, isLoadingNewLocator, hasMore} =
    restApi.endpoints.getTestProblemTestOccurrencesNormalized.useQuery(arg, {
      selectFromResult: ({data, currentData, isLoading}) => ({
        ids: data?.data.result ?? emptyArray,
        isReady: data != null,
        isLoading,
        isLoadingNewLocator: data !== currentData,
        hasMore: data?.hasMore && !data?.loadedLessThanRequested,
      }),
    })

  const getTestOccurrencesList = useMemo(makeGetTestOccurrencesList, [])
  const {currentFailures, firstFailures} = useAppSelector(
    state => getTestOccurrencesList(state, occurrenceIds),
    shallowEqual,
  )

  const [activeTab, setActiveTab] = useState(FailureTab.CURRENT_FAILURE)
  const firstFailureActive = activeTab === FailureTab.FIRST_FAILURE

  const onCurrentFailureTabClick = useCallback(() => {
    setActiveTab(FailureTab.CURRENT_FAILURE)
  }, [])

  const onFirstFailureTabClick = useCallback(() => {
    setActiveTab(FailureTab.FIRST_FAILURE)
  }, [])

  const onShowTestHistory = useCallback(() => {
    navigate(getTestHistoryHref(testId, {currentProjectId: stringifyId(projectId)}))
  }, [navigate, testId, projectId])

  const onShowInvestigationHistory = useCallback(
    () => dispatch(openDialog(stringifyId(testId), DialogType.INVESTIGATION_HISTORY)),
    [dispatch, testId],
  )

  const renderList = useCallback(
    (testOccurrences: ReadonlyArray<TestOccurrence>) => (
      <>
        {testOccurrences.map(testOccurrence => (
          <FailureRow key={testOccurrence.id} testOccurrence={testOccurrence} />
        ))}
      </>
    ),
    [],
  )

  const onShowMore = useCallback(() => {
    setStart(prevState => prevState + 1)
  }, [])

  useEffect(() => {
    setOccurrenceIds(prevState => [...prevState, ...ids])
  }, [ids])

  return (
    <>
      <div className={styles.links}>
        <Button
          inline
          className={styles.linkButton}
          height={ControlsHeight.S}
          onClick={onShowTestHistory}
        >
          {'Test History'}
        </Button>
        <Button
          inline
          className={styles.linkButton}
          height={ControlsHeight.S}
          onClick={onShowInvestigationHistory}
        >
          {'Investigation history'}
        </Button>
      </div>
      {isLoading ? (
        <div className={styles.loader}>
          <LoaderInline>{'Loading...'}</LoaderInline>
        </div>
      ) : !!currentFailures.length && !!firstFailures.length ? (
        <>
          <ButtonGroup className={styles.tabs}>
            <Button
              active={activeTab === FailureTab.CURRENT_FAILURE}
              onClick={onCurrentFailureTabClick}
            >
              {FailureTab.CURRENT_FAILURE}
            </Button>
            <Button active={firstFailureActive} onClick={onFirstFailureTabClick}>
              {FailureTab.FIRST_FAILURE}
            </Button>
          </ButtonGroup>
          <div className={styles.list}>
            <Grid className={styles.grid}>
              <RowGroup span={1}>
                <DetailedTestHeader />

                <div className={styles.failureList}>
                  {renderList(firstFailureActive ? firstFailures : currentFailures)}
                </div>
              </RowGroup>
            </Grid>
            {isLoadingNewLocator ? (
              <LoaderInline>{'Loading...'}</LoaderInline>
            ) : hasMore ? (
              <Button onClick={onShowMore}>{'Show more'}</Button>
            ) : null}
          </div>
        </>
      ) : null}
    </>
  )
}
export default memo(Failures)
