import {objectEntries} from '@jetbrains/teamcity-ui/dist/utils'
import {useCallback} from 'react'
import {useLocation, useNavigate} from 'react-router'

import {getHrefWithQueryParams} from '../../../routes'
import type {ProjectId} from '../../../types'

import type {OrderDirection} from './TableHeader/TableHeader.types'
import type {OrderByField} from './TestProblems/TestProblems.utils'

export type FilterQueryParams = {
  order?: OrderDirection | null
  orderBy?: OrderByField | null
  investigated?: string | null
  muted?: string | null
  assignee?: string | null
  projectId?: ProjectId | null
  currentlyFailing?: string | null
}

export const useChangeProblemsFilter = () => {
  const location = useLocation()
  const navigate = useNavigate()

  return useCallback(
    (filter: FilterQueryParams) => {
      const newParams = Object.fromEntries(
        objectEntries(filter).map(([key, value]) => [key, value ? String(value) : null]),
      )
      navigate(
        getHrefWithQueryParams(location, null, params => ({
          ...params,
          ...newParams,
          expandedProblem: null,
          page: null,
        })),
        {preventScrollReset: true},
      )
    },
    [location, navigate],
  )
}
