import {memo, useMemo} from 'react'
import {useLocation} from 'react-router'

import {queryToObject} from '../../../../../../utils/queryParams'
import RowGroup from '../../../../../common/Grid/RowGroup'
import TableHeader from '../../../TableHeader/TableHeader.container'
import type {Column} from '../../../TableHeader/TableHeader.types'
import {OrderDirection} from '../../../TableHeader/TableHeader.types'
import {OrderByField} from '../../TestProblems.utils'

import styles from './TestProblemHeader.module.css'

type Props = {
  count: number
  selectedCount: number
  withSelection?: boolean
  onToggleAllSelected?: () => void
}
function TestProblemHeader({
  count,
  selectedCount,
  withSelection = true,
  onToggleAllSelected,
}: Props) {
  const location = useLocation()

  const {order = OrderByField.NEW_FAILURE, orderBy = OrderDirection.DESC} = queryToObject(
    location?.search,
  )

  const columns: Column[] = useMemo(
    () => [
      {
        type: OrderByField.STATUS,
        className: styles.statusColumn,
        withCheckbox: withSelection,
        checkboxTitle: 'Select all problems',
      },
      {
        type: OrderByField.NAME,
        name: 'Test Name',
        className: styles.testNameColumn,
      },
      {
        type: OrderByField.FAILURE_COUNT,
        name: 'Number of test failures',
        withSorting: true,
        className: styles.failuresColumn,
      },
      {
        type: OrderByField.ASSIGNMENT,
        name: 'Assigned by / Assignee / Comment',
        className: styles.assignedColumn,
      },
      {
        type: 'actions',
        name: '',
        className: styles.actionsColumn,
      },
    ],
    [withSelection],
  )

  return (
    <RowGroup span={1}>
      <TableHeader
        columns={columns}
        rowsCount={count}
        selectedRowsCount={selectedCount}
        orderBy={orderBy!}
        order={order!}
        onToggleSelection={onToggleAllSelected}
      />
    </RowGroup>
  )
}
export default memo(TestProblemHeader)
