import classnames from 'classnames'
import {memo, type MouseEvent, useCallback} from 'react'

import {useAppSelector} from '../../../../../../../hooks/react-redux'
import type {ProblemOccurrenceId} from '../../../../../../../types'
import Icon from '../../../../../../common/Icon/Icon'
import {getBuildProblem} from '../../../BuildProblems.selectors'

import styles from './BuildProblemName.module.css'

type Props = {
  buildProblemId: ProblemOccurrenceId
  fullText?: boolean
  compact?: boolean
}

function BuildProblemName({buildProblemId, fullText, compact}: Props) {
  const entry = useAppSelector(state => getBuildProblem(state, buildProblemId))

  const {build, problemOccurrence} = entry ?? {}
  const statusText = build?.statusText
  const newFailure = problemOccurrence?.newFailure
  const details = problemOccurrence?.details

  // this handler is required for manual text selection
  const mouseDownHandler = useCallback((event: MouseEvent<HTMLDivElement>) => {
    event.stopPropagation()
  }, [])

  return (
    <>
      {/* eslint-disable-next-line jsx-a11y/no-static-element-interactions */}
      <div
        className={classnames(styles.name, styles.text, {
          [styles.newFailure]: newFailure,
          [styles.full]: fullText,
          [styles.compact]: compact,
        })}
        onMouseDown={mouseDownHandler}
      >
        {details}
      </div>
      {statusText && (
        <div className={styles.status}>
          <span
            className={classnames(styles.statusText, {
              [styles.full]: fullText,
            })}
          >
            <Icon className={styles.icon} name="exception" />
            {statusText}
          </span>
        </div>
      )}
    </>
  )
}
export default memo(BuildProblemName)
