import type {KeyValue} from '@jetbrains/teamcity-ui/dist/utils'
import {createSelector} from 'reselect'

import type {State} from '../../../../reducers/types'
import type {
  BuildProblem,
  GetBuildProblemTreeApiArg,
  Investigation,
  Mute,
} from '../../../../services/rest'
import {restApi} from '../../../../services/rest'
import type {ProblemOccurrenceId, ProblemsTreeNodeId} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'
import {getLeavesHash, mergeTreeAndSubTrees, sortByDepthSubtreesKeys} from '../../Tests/Tests.utils'

import type {BuildProblemsSubtree} from './BuildProblems.reducers'
import {selectedBuildProblems} from './BuildProblems.slices'
import type {BuildProblemsTreeLeaf, BuildProblemsTreeNode} from './BuildProblems.types'

const getBuildProblems: (state: State) => KeyValue<ProblemOccurrenceId, BuildProblem> = state =>
  state.entities.buildProblems

export const getBuildProblem: (
  state: State,
  id?: ProblemOccurrenceId,
) => BuildProblem | undefined = (state, id) => getBuildProblems(state)[id!]

const getBuildProblemsMutes: (
  state: State,
) => KeyValue<ProblemOccurrenceId, ReadonlyArray<Mute>> = state => state.entities.buildProblemsMutes

export const getBuildProblemMutes: (
  state: State,
  id?: ProblemOccurrenceId,
) => ReadonlyArray<Mute> | undefined = (state, id) => getBuildProblemsMutes(state)[id!]

const getBuildProblemsInvestigations: (
  state: State,
) => KeyValue<ProblemOccurrenceId, ReadonlyArray<Investigation>> = state =>
  state.entities.buildProblemsInvestigations

export const getBuildProblemInvestigations: (
  state: State,
  id?: ProblemOccurrenceId,
) => ReadonlyArray<Investigation> | undefined = (state, id) =>
  getBuildProblemsInvestigations(state)[id!]

const getBuildProblemsSubtrees: (
  state: State,
  locator: string,
) => KeyValue<string, BuildProblemsSubtree> | undefined | null = (state, locator) =>
  state.buildProblemsSubtree.buildProblemsSubtree[locator]

const getSortedByDepthSubtreesKeys: (state: State, locator: string) => ReadonlyArray<string> =
  createSelector([getBuildProblemsSubtrees], subtrees =>
    sortByDepthSubtreesKeys(subtrees, item => item?.depth),
  )

export const getBuildProblemsTreeNodes: (
  state: State,
  arg: GetBuildProblemTreeApiArg,
) => ReadonlyArray<BuildProblemsTreeNode> | undefined | null = createSelector(
  [
    (state: State, arg: GetBuildProblemTreeApiArg) =>
      restApi.endpoints.getBuildProblemsTree.select(arg)(state).data?.tree.node,
    (state: State, arg: GetBuildProblemTreeApiArg) =>
      getBuildProblemsSubtrees(state, arg.treeLocator),
    (state: State, arg: GetBuildProblemTreeApiArg) =>
      getSortedByDepthSubtreesKeys(state, arg.treeLocator),
  ],
  (treeNodes, subtrees, keys) =>
    mergeTreeAndSubTrees(treeNodes, keys, key => subtrees?.[key]?.data.node),
)

export const getBuildProblemsLeavesHash: (
  state: State,
  arg: GetBuildProblemTreeApiArg,
) => KeyValue<ProblemsTreeNodeId, BuildProblemsTreeLeaf> = createSelector(
  [
    (state: State, arg: GetBuildProblemTreeApiArg) =>
      restApi.endpoints.getBuildProblemsTree.select(arg)(state).data?.tree.leaf,
    (state: State, arg: GetBuildProblemTreeApiArg) =>
      getBuildProblemsSubtrees(state, arg.treeLocator),
    (state: State, arg: GetBuildProblemTreeApiArg) =>
      getSortedByDepthSubtreesKeys(state, arg.treeLocator),
  ],
  (treeLeaves, subtrees, keys) =>
    getLeavesHash(treeLeaves, keys, key => subtrees?.[key]?.data?.leaf),
)

export const makeGetBuildProblemsByIds: () => (
  state: State,
  ids: ReadonlyArray<ProblemOccurrenceId>,
) => ReadonlyArray<BuildProblem> = () =>
  createSelector(
    [getBuildProblems, (_: State, ids: ReadonlyArray<ProblemOccurrenceId>) => ids],
    (
      problems: KeyValue<ProblemOccurrenceId, BuildProblem>,
      ids: ReadonlyArray<ProblemOccurrenceId>,
    ) =>
      ids.length > 0
        ? Object.values(problems).filter(
            problem =>
              problem?.problemOccurrence?.id && ids?.includes(problem?.problemOccurrence?.id),
          )
        : emptyArray,
  )

export const getSelectedBuildProblems: (state: State) => ProblemOccurrenceId[] = state =>
  state.selectedBuildProblems.selectedIds

export const setSelectedIds = selectedBuildProblems.actions.setSelectedIds
