import {memo} from 'react'

import {useAppSelector} from '../../../../../../../hooks/react-redux'
import type {TestId} from '../../../../../../../types'
import Investigations from '../../../../Investigations/Investigations'
import {getTestProblemInvestigations} from '../../../TestProblems.selectors'

type Props = {
  testId?: TestId
  expanded?: boolean
  onToggle?: () => void
}

function TestInvestigations({testId, expanded, onToggle}: Props) {
  const investigations = useAppSelector(state => getTestProblemInvestigations(state, testId))

  return <Investigations investigations={investigations} expanded={expanded} onToggle={onToggle} />
}

export default memo(TestInvestigations)
