import {memo} from 'react'

import {useIsAutodetectTimeZone} from '../../../../../../../../hooks/useIsAutodetectTimeZone'
import type {TestOccurrence} from '../../../../../../../../services/rest'
import {displayDate} from '../../../../../../../../utils/dateTimeUtils'
import BuildBranch from '../../../../../../../common/BranchLabel/BuildBranchLabel.container'
import BuildPathAndStatus from '../../../../../../../common/BuildPathAndStatus/BuildPathAndStatus'
import RowGroup from '../../../../../../../common/Grid/RowGroup'
import Icon from '../../../../../../../common/Icon/Icon'
import BuildChangesDropdown from '../../../../../../Changes/BuildChangesDropdown/BuildChangesDropdown'
import {TestStatus as TestStatusEnum} from '../../../../../../Tests/Tests.types'

import FailureActions from './FailureActions/FailureActions'

import styles from './FailureRow.module.css'

const FAILURE_STATUS_LABEL = 'Failure'

type Props = {
  testOccurrence?: TestOccurrence
}
function FailureRow({testOccurrence}: Props) {
  const isAutodetectTimeZone = useIsAutodetectTimeZone()

  const {id, status, build} = testOccurrence ?? {}
  const buildId = build?.id

  if (!testOccurrence) {
    return null
  }

  return (
    <RowGroup key={id} span={2} className={styles.row}>
      <div className={styles.statusColumn}>
        {status === TestStatusEnum.FAILURE && (
          <div className={styles.status}>
            <Icon className={styles.icon} name="close" />
            {FAILURE_STATUS_LABEL}
          </div>
        )}
      </div>
      <div className={styles.projectScopeColumn}>
        <div className={styles.projectScope}>
          <div className={styles.buildPathContainer}>
            {buildId && <BuildBranch buildId={buildId} defaultTrim />}
            <BuildPathAndStatus
              buildTypeId={build?.buildTypeId}
              buildId={buildId}
              withLeafStatusIcon={false}
              withIcon={false}
              className={styles.buildPathAndStatus}
              buildStatusClassName={styles.buildStatus}
              buildPathClassName={styles.buildPath}
            />
          </div>
        </div>
      </div>
      <div className={styles.changesColumn}>
        {buildId && (
          <BuildChangesDropdown buildId={buildId} className={styles.buildChangesDropdown} />
        )}
      </div>
      <div className={styles.startedColumn}>
        <div className={styles.started}>
          {build?.startDate != null && displayDate(build?.startDate, isAutodetectTimeZone, true)}
        </div>
      </div>
      <div className={styles.actionsColumn}>
        <FailureActions testOccurrence={testOccurrence} />
      </div>
    </RowGroup>
  )
}
export default memo(FailureRow)
