import type {KeyValue, WritableKeyValue} from '@jetbrains/teamcity-ui/dist/utils'

import type {ProblemOccurrenceId, ProblemsTreeNodeId, ProjectId} from '../../../../types'
import {toProjectId, stringifyId} from '../../../../types'
import type {Node, NodeValue} from '../../../common/Tree/Tree.types'

import BuildProblemList from './BuildProblemList/BuildProblemList'
import type {
  AdvancedNode,
  BuildProblemsTreeLeaf,
  BuildProblemsTreeNode,
} from './BuildProblems.types'
import {TreeEntityType} from './BuildProblems.types'
import styles from './BuildProblemsTree/BuildProblemsTree.module.css'
import ProblemsTreeNode from './BuildProblemsTree/BuildProblemsTreeNode/BuildProblemsTreeNode'
import BuildProblemsTreeNodeFooter from './BuildProblemsTree/BuildProblemsTreeNodeFooter/BuildProblemsTreeNodeFooter'

export const generateBuildProblemsTree = (
  projectId: ProjectId | undefined,
  dataNodes: ReadonlyArray<BuildProblemsTreeNode>,
  dataLeavesHash: KeyValue<ProblemsTreeNodeId, BuildProblemsTreeLeaf>,
  treeLocator: string,
  selectedIds: ProblemOccurrenceId[],
  onSelectedIdsChange: (ids: ProblemOccurrenceId[]) => void,
  onSaveMuteInvestigation: () => void,
): Node | null => {
  let root = null
  const map: WritableKeyValue<string, number> = {}
  const advancedDataNodeHash: WritableKeyValue<NodeValue, AdvancedNode> = {}

  if (dataNodes.length === 0) {
    return null
  }

  const nodes: ReadonlyArray<Node> = dataNodes.map((dataNode, index) => {
    const {id, name} = dataNode
    map[id] = index
    advancedDataNodeHash[id] = {
      ...dataNode,
      abstractParents: [],
      allParents: [],
    }

    return {
      value: id,
      label: name,
      children: [], // Default value
    }
  })

  for (let index = 0; index < dataNodes.length; index++) {
    const {parentId} = dataNodes[index]

    const node = nodes[index]
    const packageIndex = map[stringifyId(parentId)]

    if (node.label === projectId) {
      root = node
    } else {
      const children = packageIndex != null ? nodes[packageIndex].children : null
      if (Array.isArray(children)) {
        children.push(node)
      }
    }
  }

  const findAllParents = (node: Node, parentName?: ProjectId | null): void => {
    if (node.children != null) {
      const advancedDataNode = advancedDataNodeHash[node.value]
      if (advancedDataNode == null) {
        return
      }

      const {allParents = [], ...abstractNode} = advancedDataNode

      node.children.forEach(child => {
        const childNode = advancedDataNodeHash[child.value]
        if (childNode != null) {
          childNode.allParents = [...allParents, abstractNode]
          childNode.parentProjectLabel = parentName
          findAllParents(
            child,
            childNode.type === TreeEntityType.PROJECT ? toProjectId(childNode.name) : parentName,
          )
        }
      })
    }
  }

  if (root != null) {
    findAllParents(root, root.label != null ? toProjectId(root.label) : null)
  }

  const addComponents = (parent: Node) => {
    const {children} = parent

    if (children == null) {
      return
    }

    for (let i = 0; i < children.length; i++) {
      const advancedDataNode = advancedDataNodeHash[children[i].value]

      if (advancedDataNode != null) {
        const {
          type,
          id,
          parentProjectLabel,
          childrenCount,
          problemCount,
          allParents = [],
        } = advancedDataNode
        if (
          childrenCount === 0 &&
          (type === TreeEntityType.BUILD_TYPE || type === TreeEntityType.SPLIT_BUILD)
        ) {
          const problems = dataLeavesHash[id]?.problemEntries?.entry ?? []
          const firstChildId = dataLeavesHash[id]?.nodeId
          children[i].children = [
            {
              value: stringifyId(`${firstChildId}-child`),
              label: `Build Problems`,
              labelClassName: styles.leaf,
              component: (
                <BuildProblemList
                  projectId={parentProjectLabel}
                  buildProblems={problems}
                  selectedIds={selectedIds}
                  onSelectedIdsChange={onSelectedIdsChange}
                  onSaveMuteInvestigation={onSaveMuteInvestigation}
                />
              ),
              expandable: false,
            },
          ]
        }

        children[i] = {
          ...children[i],
          labelClassName: styles.node,
          expandable: true,
          component: <ProblemsTreeNode dataNode={advancedDataNode} />,
          footerComponent: (
            <BuildProblemsTreeNodeFooter
              node={children[i]}
              type={type}
              childrenCount={childrenCount}
              problemCount={problemCount}
              childrenProblemCount={
                dataLeavesHash[id]?.problemEntries?.entry?.length ?? children[i].children?.length
              }
              depth={allParents.length}
              treeLocator={treeLocator}
            />
          ),
        }

        addComponents(children[i])
      }
    }
  }

  if (root) {
    const advancedDataNode = advancedDataNodeHash[root.value]

    if (advancedDataNode != null) {
      const {type, childrenCount, problemCount, allParents = []} = advancedDataNode
      root.footerComponent = (
        <BuildProblemsTreeNodeFooter
          node={root}
          type={type}
          childrenCount={childrenCount}
          problemCount={problemCount}
          childrenProblemCount={root.children?.length}
          depth={allParents.length}
          treeLocator={treeLocator}
        />
      )
    }

    addComponents(root)
  }

  return root
}
