import Button from '@jetbrains/ring-ui-built/components/button/button'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {memo, useCallback} from 'react'

import {restApi} from '../../../../../../services/rest'
import {EXPAND_ARROW_WIDTH, TREE_INDENT_WIDTH} from '../../../../../common/Tree/Tree.consts'
import type {Node} from '../../../../../common/Tree/Tree.types'
import {TreeEntityType} from '../../BuildProblems.types'

import styles from './BuildProblemsTreeNodeFooter.module.css'

type Props = {
  level?: number
  node: Node
  type: TreeEntityType
  childrenCount: number | null | undefined
  problemCount: number | null | undefined
  childrenProblemCount: number | null | undefined
  treeLocator: string
  depth: number
}

function BuildProblemsTreeNodeFooter({
  level = 0,
  type,
  problemCount,
  childrenCount,
  childrenProblemCount,
  node,
  treeLocator,
  depth,
}: Props) {
  const subTreeRootId = node?.value

  const [fetchBuildProblemsSubtree, {loading}] =
    restApi.endpoints.getBuildProblemsTree.useLazyQuery({
      selectFromResult: ({isLoading}) => ({loading: isLoading}),
    })

  const onClick = useCallback(() => {
    fetchBuildProblemsSubtree({
      subTreeRootId,
      locator: [treeLocator, `subTreeRootId:${subTreeRootId}`].filter(Boolean).join(','),
      depth,
      subTreeKey: subTreeRootId,
      treeLocator,
    })
  }, [depth, fetchBuildProblemsSubtree, subTreeRootId, treeLocator])

  const overallChildrenCount =
    childrenCount === 0 &&
    (type === TreeEntityType.BUILD_TYPE || type === TreeEntityType.SPLIT_BUILD)
      ? problemCount
      : childrenCount
  const style = {paddingLeft: level * TREE_INDENT_WIDTH + EXPAND_ARROW_WIDTH}

  return overallChildrenCount != null &&
    childrenProblemCount != null &&
    childrenProblemCount < overallChildrenCount ? (
    <div style={style}>
      <Button className={styles.button} onClick={onClick} disabled={loading} inline>
        {`Show all ${overallChildrenCount} items`}
      </Button>
      {loading && <LoaderInline />}
    </div>
  ) : null
}

export default memo<Props>(BuildProblemsTreeNodeFooter)
