import {memo} from 'react'

import {useAppSelector} from '../../../../../../../hooks/react-redux'
import type {ProblemOccurrenceId} from '../../../../../../../types'
import ProblemStatus from '../../../../ProblemStatus/ProblemStatus'
import {getBuildProblemInvestigations, getBuildProblemMutes} from '../../../BuildProblems.selectors'

type Props = {
  buildProblemId: ProblemOccurrenceId
}

function BuildProblemStatus({buildProblemId}: Props) {
  const mutes = useAppSelector(state => getBuildProblemMutes(state, buildProblemId))
  const investigations = useAppSelector(state =>
    getBuildProblemInvestigations(state, buildProblemId),
  )

  return <ProblemStatus mutes={mutes} investigations={investigations} />
}
export default memo(BuildProblemStatus)
