import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import classNames from 'classnames'
import {memo, useCallback, useMemo} from 'react'

import EntityPath from '../../../../../../containers/EntityPath'
import {useAppSelector} from '../../../../../../hooks/react-redux'
import {getFullPath} from '../../../../../../selectors'
import {getProjectBuildTypeFilter, toBuildTypeId, toProjectId} from '../../../../../../types'
import OverviewStatusIcon from '../../../../../common/ProjectOrBuildTypeIcon/OverviewStatusIcon.container'
import type {OverviewHeaderIconAddProps} from '../../../../../common/ProjectOrBuildTypeIcon/ProjectOrBuildTypeIcon.types'
import {EntityIconType} from '../../../../../common/ProjectOrBuildTypeIcon/ProjectOrBuildTypeIcon.types'
import type {AdvancedNode} from '../../BuildProblems.types'
import {TreeEntityType} from '../../BuildProblems.types'

import styles from './BuildProblemsTreeNode.module.css'

type Props = {
  dataNode: AdvancedNode
}

function BuildProblemsTreeNode({dataNode}: Props) {
  const {name, problemCount, abstractParents = [], type} = dataNode
  const projectId = type === TreeEntityType.PROJECT ? toProjectId(name) : undefined
  const buildTypeId =
    type === TreeEntityType.BUILD_TYPE || type === TreeEntityType.SPLIT_BUILD
      ? toBuildTypeId(name)
      : undefined

  const projectBuildTypeFilter = getProjectBuildTypeFilter({projectId, buildTypeId})
  const path = useAppSelector(state => getFullPath(state, projectBuildTypeFilter))

  const fullNodePath = useMemo(() => [...abstractParents, dataNode], [abstractParents, dataNode])

  const renderEntityPath = useCallback(
    (nodePath: Array<AdvancedNode>) => {
      const abstractParentsIds = nodePath.map(el => el.name)
      const filterdPath = path.filter(pathItem => abstractParentsIds.includes(pathItem.id!))
      const iconProps: OverviewHeaderIconAddProps =
        type === TreeEntityType.PROJECT
          ? {type: EntityIconType.PROJECT, id: projectId}
          : {type: EntityIconType.BUILD_TYPE, id: buildTypeId}
      return (
        <>
          <H2
            className={classNames(styles.entityPath, {
              [styles.buildType]: type === TreeEntityType.BUILD_TYPE,
            })}
          >
            <OverviewStatusIcon {...iconProps} size={type === TreeEntityType.PROJECT ? 'L' : 'M'} />
            <EntityPath
              linkClassName={styles.entityPathLink}
              projectId={projectId}
              buildTypeId={buildTypeId}
              path={filterdPath}
              projectOrBuildTypeNode={{nodeType: 'all'}}
              withLeafStatusIcon={false}
              withLeafIcon={false}
            />
          </H2>

          <div className={styles.childrenCount}>{problemCount}</div>
        </>
      )
    },
    [buildTypeId, path, problemCount, projectId, type],
  )

  const renderPath = useMemo(() => renderEntityPath(fullNodePath), [fullNodePath, renderEntityPath])

  return (
    <div className={styles.detailedNode}>
      {type === TreeEntityType.SPLIT_BUILD ? (
        <>
          <H2 className={classNames(styles.entityPath, styles.buildType)}>{name}</H2>
          <div className={styles.childrenCount}>{problemCount}</div>
        </>
      ) : (
        renderPath
      )}
    </div>
  )
}

export default memo<Props>(BuildProblemsTreeNode)
