import Button from '@jetbrains/ring-ui-built/components/button/button'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {memo, Suspense, useCallback, useMemo, useRef, useState} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../hooks/react-redux'
import type {GetBuildProblemTreeApiArg} from '../../../../../services/rest'
import {restApi} from '../../../../../services/rest'
import type {ProblemOccurrenceId, ProjectId} from '../../../../../types'
import {emptyArray} from '../../../../../utils/empty'
import InvestigationStatusFilter from '../../../../common/InvestigationStatusFilter/InvestigationStatusFilter'
import MuteStatusFilter from '../../../../common/MuteStatusFilter/MuteStatusFilter'
import Placeholder from '../../../../common/Placeholder/Placeholder'
import Tree, {type Handle} from '../../../../common/Tree/Tree'
import {getTreeNodes} from '../../../../common/Tree/Tree.utils'
import ProjectBuildTypeFilter from '../../ProjectBuildTypeFilter/ProjectBuildTypeFilter'
import {useWidthResize} from '../BuildProblems.context'
import {
  getBuildProblemsLeavesHash,
  getBuildProblemsTreeNodes,
  getSelectedBuildProblems,
  setSelectedIds,
} from '../BuildProblems.selectors'
import {TreeEntityType} from '../BuildProblems.types'
import {generateBuildProblemsTree} from '../BuildProblems.utils'

import BatchActions from './BatchActions/BatchActions'
import BuildProblemsTreeNodeFooter from './BuildProblemsTreeNodeFooter/BuildProblemsTreeNodeFooter'

import styles from './BuildProblemsTree.module.css'

const PLACEHOLDER_LABEL = 'There are no build problems found.'

type Props = {
  projectId?: ProjectId
  locator: string
  arg: GetBuildProblemTreeApiArg
  onlyInvestigated?: boolean
  isLoading?: boolean
}
function BuildProblemsTree({projectId, locator, arg, onlyInvestigated, isLoading}: Props) {
  const dispatch = useAppDispatch()
  const {ref} = useWidthResize()
  const treeRef = useRef<Handle>(null)

  const {refetch} = restApi.endpoints.getBuildProblemsTree.useQuerySubscription(arg)

  const treeNodes = useAppSelector(state => getBuildProblemsTreeNodes(state, arg))
  const leavesHash = useAppSelector(state => getBuildProblemsLeavesHash(state, arg))

  const selectedIds = useAppSelector(state => getSelectedBuildProblems(state))

  const onSelectedIdsChange = useCallback(
    (ids: ProblemOccurrenceId[]) => {
      dispatch(setSelectedIds(ids))
    },
    [dispatch],
  )

  const onClearSelection = useCallback(() => {
    dispatch(setSelectedIds([]))
  }, [dispatch])

  const onSaveMuteInvestigation = useCallback(() => {
    onClearSelection()
    refetch()
  }, [onClearSelection, refetch])

  const treeRoot = useMemo(
    () =>
      treeNodes != null
        ? generateBuildProblemsTree(
            projectId,
            treeNodes,
            leavesHash,
            locator,
            selectedIds,
            onSelectedIdsChange,
            onSaveMuteInvestigation,
          )
        : null,
    [
      projectId,
      treeNodes,
      leavesHash,
      locator,
      selectedIds,
      onSelectedIdsChange,
      onSaveMuteInvestigation,
    ],
  )
  const treeRootChildren = treeRoot?.children ?? emptyArray
  const flatTreeNodes = useMemo(() => getTreeNodes(treeRootChildren), [treeRootChildren])

  const rootNode = useMemo(
    () => treeNodes?.find(node => node.name === projectId),
    [treeNodes, projectId],
  )

  const defaultExpandedState: readonly string[] = useMemo(
    () => flatTreeNodes.filter(node => node.expandable).map(node => `${node.value}`),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  )

  const [expandedNodes, setExpandedNodes] = useState<readonly string[]>(defaultExpandedState)

  const onExpand = useCallback(
    (newExpandedState: readonly string[]) => setExpandedNodes(newExpandedState),
    [],
  )

  const onExpandAll = useCallback(() => {
    if (treeRef.current?.onExpandAll != null) {
      treeRef.current.onExpandAll()
    }
  }, [])

  const onCollapseAll = useCallback(() => {
    if (treeRef.current?.onCollapseAll != null) {
      treeRef.current.onCollapseAll()
    }
  }, [])

  return (
    <>
      <div className={styles.row} ref={ref}>
        {onlyInvestigated && <ProjectBuildTypeFilter onChange={onClearSelection} />}
        <MuteStatusFilter />
        {!onlyInvestigated && <InvestigationStatusFilter />}
        <Button onClick={onExpandAll}>{'Expand all'}</Button>
        <Button onClick={onCollapseAll}>{'Collapse all'}</Button>
      </div>
      {isLoading ? (
        <span>
          <LoaderInline>{'Loading...'}</LoaderInline>
        </span>
      ) : !flatTreeNodes.length ? (
        <Placeholder message={PLACEHOLDER_LABEL} />
      ) : (
        <Suspense>
          <Tree
            labelId={'buildProblems'}
            id="build-problems-tree"
            ref={treeRef}
            className={styles.tree}
            checkable={false}
            expanded={expandedNodes}
            nodes={treeRootChildren}
            onExpand={onExpand}
          />
          {treeRoot ? (
            <BuildProblemsTreeNodeFooter
              node={treeRoot}
              type={TreeEntityType.PROJECT}
              childrenCount={rootNode?.childrenCount}
              problemCount={rootNode?.problemCount}
              childrenProblemCount={treeRoot.children?.length}
              depth={1}
              treeLocator={locator}
            />
          ) : null}
          <BatchActions
            projectId={projectId}
            selectedIds={selectedIds}
            onClear={onClearSelection}
            onSaveMuteInvestigation={onSaveMuteInvestigation}
          />
        </Suspense>
      )}
    </>
  )
}

export default memo(BuildProblemsTree)
