import Button from '@jetbrains/ring-ui-built/components/button/button'
import plur from 'plur'
import {memo, useCallback, useMemo} from 'react'
import {shallowEqual} from 'react-redux'

import {useAppDispatch, useAppSelector} from '../../../../../../hooks/react-redux'
import {usePermission} from '../../../../../../hooks/usePermission'
import type {ProjectId, TestId} from '../../../../../../types'
import {Permission} from '../../../../../../types'
import ServiceMessage from '../../../../../common/ServiceMessage/ServiceMessage'
import {assignTestInvestigations} from '../../../../Tests/Tests.actions'
import {makeGetTestProblemsByTestIds} from '../../TestProblems.selectors'

import styles from './BatchAction.module.css'

type Props = {
  projectId?: ProjectId | null
  selectedIds: TestId[]
  onClear: () => void
  onSaveMuteInvestigation: () => void
}

enum TestBatchAction {
  INVESTIGATE = 'Investigate',
  FIX = 'Fix',
  MUTE = 'Mute',
}

function BatchActions({projectId, selectedIds, onClear, onSaveMuteInvestigation}: Props) {
  const dispatch = useAppDispatch()
  const hasPermissionForInvestigation = usePermission(Permission.ASSIGN_INVESTIGATION, projectId)
  const hasPermissionForMute = usePermission(Permission.MANAGE_BUILD_PROBLEMS, projectId)

  const selectedCount = selectedIds.length

  const getTestProblemsByTestIds = useMemo(makeGetTestProblemsByTestIds, [])
  const selectedProblems = useAppSelector(
    state => getTestProblemsByTestIds(state, selectedIds),
    shallowEqual,
  )

  const problems = useMemo(
    () =>
      selectedProblems
        .map(problem => problem?.test?.id)
        .filter(testId => testId != null) as TestId[],
    [selectedProblems],
  )

  const onMute = useCallback(() => {
    dispatch(assignTestInvestigations(projectId, problems, [], [], false, onSaveMuteInvestigation))
  }, [dispatch, onSaveMuteInvestigation, problems, projectId])

  const onFix = useCallback(() => {
    dispatch(assignTestInvestigations(projectId, problems, [], [], true, onSaveMuteInvestigation))
  }, [dispatch, onSaveMuteInvestigation, problems, projectId])

  const onInvestigate = useCallback(() => {
    dispatch(assignTestInvestigations(projectId, problems, [], [], false, onSaveMuteInvestigation))
  }, [dispatch, onSaveMuteInvestigation, problems, projectId])

  const controls = (
    <div className={styles.actions}>
      {hasPermissionForInvestigation && (
        <>
          <Button primary onClick={onInvestigate}>
            {TestBatchAction.INVESTIGATE}
          </Button>
          <Button className={styles.secondary} inline onClick={onFix}>
            {TestBatchAction.FIX}
          </Button>
        </>
      )}
      {hasPermissionForMute && (
        <Button className={styles.secondary} inline onClick={onMute}>
          {TestBatchAction.MUTE}
        </Button>
      )}
    </div>
  )

  if (selectedCount === 0 || (!hasPermissionForInvestigation && !hasPermissionForMute)) {
    return null
  }

  return (
    <ServiceMessage
      closeable
      icon="task"
      controls={controls}
      onClose={onClear}
      title={`${selectedCount} ${plur('Problem', selectedCount)} Selected`}
    >
      {
        'Choose a person responsible for resolving the selected problems, or mark them as fixed or muted.'
      }
    </ServiceMessage>
  )
}

export default memo(BatchActions)
