import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import classNames from 'classnames'
import type {ReactNode} from 'react'
import {memo, useCallback} from 'react'

import Icon from '../../../common/Icon/Icon'
import ValueToClickAction from '../../../common/ValueToClickAction/ValueToClickAction'

import type {Props} from './TableHeader.types'
import {OrderDirection} from './TableHeader.types'

import styles from './TableHeader.module.css'

function TableHeader({
  columns,
  rowsCount,
  selectedRowsCount,
  orderBy,
  order,
  onChangeQueryParams,
  onToggleSelection,
}: Props) {
  const isSelectedAll = rowsCount === selectedRowsCount
  const onChangeSorting = useCallback(
    (newOrderBy: string, priorityOrder: OrderDirection = OrderDirection.ASC) => {
      let newOrder = priorityOrder

      if (newOrderBy === orderBy) {
        newOrder = order === OrderDirection.ASC ? OrderDirection.DESC : OrderDirection.ASC
      }

      onChangeQueryParams({
        orderBy: newOrderBy,
        order: newOrder,
      })
    },
    [orderBy, order, onChangeQueryParams],
  )
  const renderColumn = useCallback(
    (
      type = '',
      name: ReactNode | string = '',
      className: string,
      withSorting = false,
      priorityOrder = OrderDirection.ASC,
      withCheckbox?: boolean,
      checkboxTitle?: string,
    ) => {
      const icon = order === OrderDirection.ASC ? 'chevron-up' : 'chevron-down'
      const sortable = (
        <ValueToClickAction
          value={type}
          onClick={value => onChangeSorting(value, priorityOrder)}
          child={
            <button type="button" className={styles.columnTitle}>
              {name}
              {orderBy === type ? (
                <Icon name={icon} />
              ) : (
                <Icon className={styles.sortIcon} name={'sorting'} />
              )}
            </button>
          }
        />
      )
      const nonSortable = name ? <span>{name}</span> : null

      return (
        <div className={classNames([styles.column], className)} key={type}>
          {withCheckbox ? (
            <Checkbox
              aria-label={checkboxTitle}
              title={checkboxTitle}
              checked={isSelectedAll}
              onChange={onToggleSelection}
            />
          ) : null}
          {withSorting ? sortable : nonSortable}
        </div>
      )
    },
    [order, onChangeSorting, orderBy, isSelectedAll, onToggleSelection],
  )

  return (
    <div className={styles.tableHeader}>
      {columns.map(
        ({name, type, withCheckbox, checkboxTitle, priorityOrder, withSorting, className}) =>
          renderColumn(
            type,
            name,
            className,
            withSorting,
            priorityOrder,
            withCheckbox,
            checkboxTitle,
          ),
      )}
    </div>
  )
}
export default memo(TableHeader)
