import classNames from 'classnames'
import type {MouseEvent} from 'react'
import {memo, useCallback} from 'react'

import {useAppSelector} from '../../../../../../../hooks/react-redux'
import type {TestId} from '../../../../../../../types'
import {getTestProblem} from '../../../TestProblems.selectors'

import {getTestNames} from './TestName.utils'

import styles from './TestName.module.css'

type TestNameProps = {
  testId?: TestId
  full?: boolean
}
function TestName({testId, full}: TestNameProps) {
  const entry = useAppSelector(state => getTestProblem(state, testId))
  const newFailure = entry?.newFailure

  const {name, suiteAndPackage} = getTestNames(entry?.test?.parsedTestName ?? {})

  // this handler is required for manual text selection
  const mouseDownHandler = useCallback((event: MouseEvent<HTMLDivElement>) => {
    event.stopPropagation()
  }, [])

  return (
    <>
      {/* eslint-disable-next-line jsx-a11y/no-static-element-interactions */}
      <div
        className={classNames(styles.name, {
          [styles.newFailure]: newFailure,
          [styles.full]: full,
        })}
        onMouseDown={mouseDownHandler}
      >
        {name}
      </div>
      <div className={classNames(styles.parameters, {[styles.full]: full})}>{suiteAndPackage}</div>
    </>
  )
}

export default memo(TestName)
