import type {Investigation} from '../../../../services/rest'

export const isSelfAssigned = ({assignee, assignment}: Investigation): boolean =>
  !assignment?.user?.username || assignee?.username === assignment?.user?.username

export const getAssigneeName = (
  {assignee}: Investigation,
  isAssignedToCurrentUser: boolean,
): string => (isAssignedToCurrentUser ? 'you' : assignee?.name || assignee?.username || '')

export const getAssignmentName = (investigation: Investigation): string => {
  const {assignment} = investigation
  return isSelfAssigned(investigation)
    ? 'Self-assigned'
    : assignment?.user?.name || assignment?.user?.username || 'Assigned'
}
