import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {memo} from 'react'

import {useIsAutodetectTimeZone} from '../../../../hooks/useIsAutodetectTimeZone'
import useMyId from '../../../../hooks/useMyId'
import type {Mute, Investigation} from '../../../../services/rest'
import type {Investigation as InvestigationType} from '../../../../types'
import {stringifyId} from '../../../../types'
import InvestigationDetails from '../../../common/Investigations/InvestigationDetails'
import MuteDetails from '../../../common/Mutes/MuteDetails'
import Popup from '../../../common/Popup/Popup.lazy'

import styles from './ProblemStatus.module.css'

const DIRECTIONS = [Directions.BOTTOM_RIGHT, Directions.TOP_RIGHT]

type Props = {
  mutes?: ReadonlyArray<Mute>
  investigations?: ReadonlyArray<Investigation>
  showUnmuted?: boolean
}

function ProblemStatus({mutes, investigations, showUnmuted = true}: Props) {
  const currentUserId = useMyId()
  const isAutodetectTimeZone = useIsAutodetectTimeZone()

  const muteAnchor = (
    <IconButton className={styles.iconButton} icon="mute" aria-label="muted" title="" />
  )
  const investigationAnchor = (
    <IconButton
      className={styles.iconButton}
      icon="investigation"
      aria-label="investigated"
      title=""
    />
  )

  if (!mutes?.length && !investigations?.length) {
    return null
  }

  return (
    <div className={styles.container}>
      {showUnmuted && !!mutes?.length ? (
        <Dropdown anchor={muteAnchor} hoverMode>
          <Popup className={styles.popup} directions={DIRECTIONS}>
            <div className={styles.content}>
              {mutes.map(mute => (
                <MuteDetails key={stringifyId(mute.id)} mute={mute} currentlyMuted />
              ))}
            </div>
          </Popup>
        </Dropdown>
      ) : null}
      {!!investigations?.length && (
        <Dropdown anchor={investigationAnchor} hoverMode>
          <Popup className={styles.popup} directions={DIRECTIONS}>
            <div className={styles.content}>
              {investigations?.map(investigation => (
                <InvestigationDetails
                  key={stringifyId(investigation.id)}
                  currentUserId={currentUserId}
                  investigation={investigation as InvestigationType}
                  isAutodetectTimeZone={isAutodetectTimeZone}
                />
              ))}
            </div>
          </Popup>
        </Dropdown>
      )}
    </div>
  )
}

export default memo(ProblemStatus)
