import Button from '@jetbrains/ring-ui-built/components/button/button'
import List from '@jetbrains/ring-ui-built/components/list/list'
import {memo, useCallback} from 'react'
import {useNavigate} from 'react-router'

import {openDialog} from '../../../../../../../actions'
import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {usePermission} from '../../../../../../../hooks/usePermission'
import {getTestHistoryHref} from '../../../../../../../routes'
import type {ProjectId, TestId} from '../../../../../../../types'
import {DialogType, Permission, stringifyId} from '../../../../../../../types'
import ArrowPopupMenu from '../../../../../../common/ArrowPopupMenu/ArrowPopupMenu'
import {MuteOption} from '../../../../../../common/MuteInvestigationDialogs/MuteDialog/MuteDialog.types'
import {assignTestInvestigations} from '../../../../../Tests/Tests.actions'
import {getTestProblemInvestigations, getTestProblemMutes} from '../../../TestProblems.selectors'

import styles from './TestActions.module.css'

type TestActionsProps = {
  testId?: TestId
  projectId?: ProjectId | null
  onSaveMuteInvestigation: () => void
}
function TestActions({testId, projectId, onSaveMuteInvestigation}: TestActionsProps) {
  const navigate = useNavigate()
  const dispatch = useAppDispatch()

  const hasPermissionForInvestigation = usePermission(Permission.ASSIGN_INVESTIGATION, projectId)
  const hasPermissionForMute = usePermission(Permission.MANAGE_BUILD_PROBLEMS, projectId)

  const investigations = useAppSelector(state => getTestProblemInvestigations(state, testId))
  const mutes = useAppSelector(state => getTestProblemMutes(state, testId))

  const currentlyMuted = !!mutes?.length
  const currentlyInvestigated = !!investigations?.length

  const muteMode = currentlyMuted ? MuteOption.UNMUTE : MuteOption.MUTE

  const onMute = useCallback(() => {
    dispatch(assignTestInvestigations(projectId, [testId], [], [], false, onSaveMuteInvestigation))
  }, [dispatch, onSaveMuteInvestigation, projectId, testId])

  const onInvestigate = useCallback(() => {
    dispatch(assignTestInvestigations(projectId, [testId], [], [], false, onSaveMuteInvestigation))
  }, [dispatch, onSaveMuteInvestigation, projectId, testId])

  const onFix = useCallback(() => {
    dispatch(assignTestInvestigations(projectId, [testId], [], [], true, onSaveMuteInvestigation))
  }, [dispatch, onSaveMuteInvestigation, projectId, testId])

  const onShowTestHistory = useCallback(() => {
    navigate(getTestHistoryHref(testId, {currentProjectId: stringifyId(projectId)}))
  }, [navigate, testId, projectId])

  const onShowInvestigationHistory = useCallback(
    () => dispatch(openDialog(stringifyId(testId), DialogType.INVESTIGATION_HISTORY)),
    [dispatch, testId],
  )

  const elements = []
  if (hasPermissionForInvestigation) {
    if (currentlyInvestigated) {
      elements.push({
        rgItemType: List.ListProps.Type.ITEM,
        label: 'Mark as Fixed Problem',
        onClick: onFix,
      })
    }
    elements.push({
      rgItemType: List.ListProps.Type.ITEM,
      label: currentlyInvestigated ? 'Reassign Investigation' : 'Assign Investigation',
      onClick: onInvestigate,
    })
  }
  elements.push({
    rgItemType: List.ListProps.Type.ITEM,
    label: 'Go to Test History',
    onClick: onShowTestHistory,
  })
  elements.push({
    rgItemType: List.ListProps.Type.ITEM,
    label: 'Show Investigation History',
    onClick: onShowInvestigationHistory,
  })

  return (
    <div className={styles.container}>
      {hasPermissionForMute && <Button onClick={onMute}>{muteMode}</Button>}
      {hasPermissionForInvestigation && <Button onClick={onInvestigate}>{'Investigate'}</Button>}
      <ArrowPopupMenu className={styles.menu} elements={elements} />
    </div>
  )
}
export default memo(TestActions)
